// Public, read-only tool APIs. This file is inlined into the dashboard-pasteable Worker.
// Use global fetch only: do not attach private-network/VPC outbound bindings to it.
const apiVersion = 'coolcode.public-api.v1';
const apiUA = 'CoolCode/1.0 (+https://coolcode.ca/; public-tool-data)';
const apiFailure = (status, code, message, retry) => ({status, body:{error:{code,message}},
  ...(retry ? {headers:{'Retry-After':String(retry)}} : {})});
const apiThrow = (status, code, message, retry) => { throw Object.assign(new Error(message), {api:true,status,code,retry}); };

function apiPublicURL(value) {
  let u;
  try { u = new URL(value); } catch { apiThrow(400,'invalid_url','Enter a public HTTPS feed URL.'); }
  const host = u.hostname.toLowerCase();
  const coolcodeFeed=host==='coolcode.ca' && !u.search && /^\/(?:civicrevision\/data\/feeds\/(?:all|institutions|rights-policy|economy|regional)|releasereceipt\/(?:feed|feeds\/v[1-9]\d{0,14}))\.xml$/.test(u.pathname);
  if (value.length>2048 || u.protocol!=='https:' || u.username || u.password || u.port || u.hash ||
      /[\\\s]/.test(value) || !/^[a-z0-9.-]+\.[a-z]{2,63}$/.test(host) || host.endsWith('.') ||
      /(^|\.)(localhost|local|internal|lan|home|test|invalid|example|onion)$/.test(host) ||
      (host==='coolcode.ca' && !coolcodeFeed) || host.endsWith('.workers.dev') ||
      [...u.searchParams.keys()].some(k=>/^(token|key|api[_-]?key|auth|password|secret|access_token)$/i.test(k))) {
    apiThrow(400,'invalid_url','Use a public HTTPS feed without credentials, tokens, custom ports or local addresses.');
  }
  return u;
}

function apiParams(url, names) {
  for (const [key] of url.searchParams) {
    if (!names.includes(key) || url.searchParams.getAll(key).length!==1) apiThrow(400,'invalid_parameter','Unsupported or repeated parameter.');
  }
  return (key, regex, fallback) => {
    const value = (url.searchParams.get(key) ?? fallback ?? '').trim();
    if (!regex.test(value)) apiThrow(400,'invalid_parameter','Check the '+key+' parameter.');
    return value;
  };
}

// Accept only the forms used by the two newspaper tools. The client supplies
// search fields; the upstream host, path, output projection and header are fixed.
function newspaperRoute(url, env) {
  const agent=env.LOC_USER_AGENT;
  if(typeof agent!=='string' || !/^[^\s@]+@[^\s@]+ [!-~]+$/.test(agent) || /[\r\n\u0000]/.test(agent) || agent.length>512)
    apiThrow(503,'not_configured','The newspaper search connection needs its Library of Congress configuration.');
  const constants={dl:'page',searchType:'advanced',fo:'json',at:'results,pagination'};
  const filters=['qs','ops','c','sp','st','start_date','end_date','location_state','location_city','partof_title','sb','fa'];
  const p=apiParams(url,[...Object.keys(constants),...filters]);
  for(const [key,value] of Object.entries(constants)){
    if(url.searchParams.get(key)!==value) apiThrow(400,'invalid_parameter','Use the newspaper page-search form.');
  }
  const target=new URL('https://www.loc.gov/collections/chronicling-america/');
  const query=p('qs',/^[^\u0000-\u001f\u007f]{0,300}$/u);
  const size=Number(p('c',/^(?:[1-9]\d?|100)$/));
  const page=Number(p('sp',/^[1-9]\d{0,5}$/));
  if((page-1)*size>=100000) apiThrow(400,'invalid_parameter','Narrow your dates or search before paging deeper.');
  target.searchParams.set('c',String(size));
  target.searchParams.set('sp',String(page));
  if(url.searchParams.has('st')) target.searchParams.set('st',p('st',/^gallery$/));
  target.searchParams.set('dl',constants.dl);
  target.searchParams.set('searchType',constants.searchType);
  target.searchParams.set('qs',query);
  target.searchParams.set('ops',p('ops',/^(?:AND|OR|PHRASE|~5|~10)$/));
  for(const key of ['start_date','end_date']){
    if(!url.searchParams.has(key)) continue;
    const value=p(key,/^\d{4}-\d{2}-\d{2}$/);
    const parsed=Date.parse(value);
    if(!Number.isFinite(parsed)||new Date(parsed).toISOString().slice(0,10)!==value) apiThrow(400,'invalid_parameter','Enter a valid newspaper date.');
    target.searchParams.set(key,value);
  }
  if(target.searchParams.has('start_date')&&target.searchParams.has('end_date')&&target.searchParams.get('start_date')>target.searchParams.get('end_date')) apiThrow(400,'invalid_parameter','The start date must precede the end date.');
  for(const key of ['location_state','location_city','partof_title']) {
    if(url.searchParams.has(key)) target.searchParams.set(key,p(key,/^[^\u0000-\u001f\u007f]{1,200}$/u));
  }
  if(url.searchParams.has('fa')) target.searchParams.set('fa',p('fa',/^number_lccn:[a-zA-Z0-9-]{4,30}$/));
  if(!query && !['start_date','end_date','location_state','location_city','partof_title','fa'].some(k=>target.searchParams.has(k))) apiThrow(400,'invalid_parameter','Enter a topic, date, town or newspaper.');
  if(url.searchParams.has('sb')) target.searchParams.set('sb',p('sb',/^(?:date|date_desc)$/));
  target.searchParams.set('fo',constants.fo);
  target.searchParams.set('at',constants.at);
  // fo=json selects LOC's representation. Match the working curl request's
  // media negotiation and use an uncompressed body for this bounded JSON read.
  return {target,group:'loc-newspapers',ttl:3600,limit:4_000_000,timeout:80000,
    maximum:15,window:60000,headers:{Accept:'*/*','Accept-Encoding':'identity','User-Agent':agent}};
}

// The owner’s diagnostic path, fixed receiver and test identity stay in a Worker secret.
async function newspaperDiagnostic(request,env) {
  let config;
  try { config=JSON.parse(env.LOC_DIAGNOSTIC_CONFIG); } catch { return null; }
  if(!config || new URL(request.url).pathname!==config.path) return null;
  const target=new URL(config.target);
  const plan=newspaperRoute(target,env);
  target.search=plan.target.search;
  const reply=await fetch(target.href,{
    headers:{...plan.headers,'User-Agent':config.userAgent},
    redirect:'manual',
    signal:AbortSignal.timeout(plan.timeout)
  });
  await reply.body?.cancel();
  return Response.json({
    receiver_status:reply.status,
    capture_id:reply.headers.get('X-Loc-Capture-Id')
  },{headers:{'Cache-Control':'no-store'}});
}
function newspaperResults(data,plan) {
  const page=Number(plan.target.searchParams.get('sp')), size=Number(plan.target.searchParams.get('c'));
  const pagination=data?.pagination;
  if(!Array.isArray(data?.results)||data.results.length>size||!pagination||
    !Number.isSafeInteger(pagination.of)||pagination.of<0||Number(pagination.current)!==page||Number(pagination.perpage)!==size)
    apiThrow(502,'invalid_source','The newspaper archive returned an unexpected results page.');
  const results=[];
  const scalar=['url','id','title','date','page_id'];
  const lists=['partof_title','location_city','location_state','number_lccn','number_page','language','contributor','image_url','description'];
  for(const row of data.results){
    if(!row||typeof row!=='object'||row.access_restricted===true||typeof row.title!=='string') continue;
    const output={};
    for(const key of scalar) if(typeof row[key]==='string') output[key]=row[key].slice(0,2048);
    for(const key of lists){
      if(Array.isArray(row[key])) output[key]=row[key].filter(v=>typeof v==='string').slice(0,12).map(v=>v.slice(0,2048));
    }
    results.push(output);
  }
  const result={results,pagination:{of:pagination.of,current:page,perpage:size,next:Boolean(pagination.next)}};
  // Inspect the final decoded values too, in case JSON escaping concealed an echo.
  const agent=plan.headers['User-Agent'];
  if(JSON.stringify(result).includes(agent.split(' ')[1])) apiThrow(502,'invalid_source','The newspaper archive returned an unexpected response.');
  return result;
}

function apiRoute(url, env) {
  if(url.pathname==='/api/newspapers/search') return newspaperRoute(url,env);
  const path=url.pathname, plan={ttl:900,limit:2_000_000,headers:{Accept:'application/json','User-Agent':apiUA}};
  let p, target;
  if (path.startsWith('/api/podcastroute/')) {
    if (!env.PODCASTINDEX_API_KEY || !env.PODCASTINDEX_API_SECRET) apiThrow(503,'not_configured','Podcast search is awaiting the site API configuration.');
    plan.group='podcast'; plan.maximum=1500; plan.window=86400000; plan.sign=true;
    target=new URL('https://api.podcastindex.org/api/1.0/');
    if (path==='/api/podcastroute/search') {p=apiParams(url,['q']); target.pathname+='search/byterm'; target.searchParams.set('q',p('q',/^.{2,120}$/u)); target.searchParams.set('max','40');}
    else if (path==='/api/podcastroute/episodes') {p=apiParams(url,['id']); target.pathname+='episodes/byfeedid'; target.searchParams.set('id',p('id',/^[1-9]\d{0,14}$/)); target.searchParams.set('max','100'); target.searchParams.set('fulltext','1');}
    else if (path==='/api/podcastroute/feed') {p=apiParams(url,['url']); target.pathname+='podcasts/byfeedurl'; target.searchParams.set('url',apiPublicURL(p('url',/^.{1,2048}$/)).href);}
    else apiThrow(404,'unknown_endpoint','Unknown podcast endpoint.');
  } else if (path.startsWith('/api/channelqueue/')) {
    if (!env.YOUTUBE_API_KEY) apiThrow(503,'not_configured','YouTube lookup is awaiting the site API configuration.');
    target=new URL('https://www.googleapis.com/youtube/v3/');
    plan.group='youtube'; plan.maximum=5000; plan.window=86400000; plan.ttl=3600;
    if (path==='/api/channelqueue/channel') {
      p=apiParams(url,['id','handle']); target.pathname+='channels';
      if (url.searchParams.has('id')===url.searchParams.has('handle')) apiThrow(400,'invalid_parameter','Choose a channel ID or handle.');
      if (url.searchParams.has('id')) target.searchParams.set('id',p('id',/^UC[\w-]{22}$/));
      else target.searchParams.set('forHandle',p('handle',/^@?[^\s/?&#]{3,100}$/u));
      target.searchParams.set('part','snippet,contentDetails');
    } else if (path==='/api/channelqueue/playlist') {
      p=apiParams(url,['id','pageToken']); target.pathname+='playlistItems';
      target.searchParams.set('playlistId',p('id',/^[\w-]{10,100}$/)); target.searchParams.set('part','snippet,contentDetails'); target.searchParams.set('maxResults','50');
      if (url.searchParams.has('pageToken')) target.searchParams.set('pageToken',p('pageToken',/^[\w=-]{1,300}$/));
    } else if (path==='/api/channelqueue/videos') {
      p=apiParams(url,['ids']); target.pathname+='videos'; const ids=p('ids',/^[\w,-]{11,599}$/).split(',');
      if (ids.length>50 || ids.some(id=>!/^[\w-]{11}$/.test(id))) apiThrow(400,'invalid_parameter','Supply up to 50 valid video IDs.');
      target.searchParams.set('id',[...new Set(ids)].sort().join(',')); target.searchParams.set('part','snippet,contentDetails,status');
    } else if (path==='/api/channelqueue/search') {
      p=apiParams(url,['q']); target.pathname+='search'; target.searchParams.set('q',p('q',/^.{2,120}$/u)); target.searchParams.set('part','snippet'); target.searchParams.set('type','channel'); target.searchParams.set('maxResults','10');
      plan.group='youtube-search'; plan.maximum=50;
    } else apiThrow(404,'unknown_endpoint','Unknown YouTube endpoint.');
    // Key is attached only after the cache identifier is computed.
    plan.keyName='key'; plan.secret=env.YOUTUBE_API_KEY;
  } else if (path.startsWith('/api/recipemath/')) {
    if (!env.FDC_API_KEY) apiThrow(503,'not_configured','USDA search is awaiting the site API configuration. Canadian foods remain available.');
    target=new URL('https://api.nal.usda.gov/fdc/v1/'); plan.group='fdc'; plan.maximum=500; plan.window=3600000; plan.ttl=86400;
    if (path==='/api/recipemath/search') {p=apiParams(url,['q','page']); target.pathname+='foods/search'; target.searchParams.set('query',p('q',/^.{2,120}$/u)); target.searchParams.set('pageNumber',p('page',/^(?:[1-9]|[1-9]\d|100)$/,'1')); target.searchParams.set('pageSize','20');}
    else if (path==='/api/recipemath/food') {p=apiParams(url,['id']); target.pathname+='food/'+p('id',/^[1-9]\d{0,11}$/);}
    else apiThrow(404,'unknown_endpoint','Unknown food endpoint.');
    plan.keyName='api_key'; plan.secret=env.FDC_API_KEY;
  } else if (path==='/api/distropilot/project') {
    p=apiParams(url,['name']); target=new URL('https://repology.org/api/v1/project/'+encodeURIComponent(p('name',/^[a-zA-Z0-9][a-zA-Z0-9+_.-]{0,99}$/)));
    plan.group='repology'; plan.maximum=600; plan.window=86400000; plan.ttl=21600; plan.limit=4_000_000; plan.timeout=35000;
  } else if (path==='/api/feedharbour/feed') {
    p=apiParams(url,['url']); target=apiPublicURL(p('url',/^.{1,2048}$/));
    plan.group='feeds'; plan.maximum=3000; plan.window=86400000; plan.feed=true;
    plan.headers.Accept='application/rss+xml, application/atom+xml, application/xml, text/xml;q=0.9';
  } else apiThrow(404,'unknown_endpoint','Unknown tool endpoint.');
  plan.target=target; return plan;
}

async function apiRead(response, limit) {
  if (Number(response.headers.get('Content-Length'))>limit) {await response.body?.cancel(); apiThrow(502,'source_too_large','The source response exceeds this tool’s size limit.');}
  if (!response.body) apiThrow(502,'empty_source','The source returned an empty response.');
  const reader=response.body.getReader(), chunks=[]; let length=0;
  try {
    while (true) {const {done,value}=await reader.read(); if(done) break; length+=value.length;
      if(length>limit) apiThrow(502,'source_too_large','The source response exceeds this tool’s size limit.'); chunks.push(value);}
  } catch(e) {await reader.cancel().catch(()=>{}); throw e;}
  const bytes=new Uint8Array(length); let at=0; for(const chunk of chunks){bytes.set(chunk,at);at+=chunk.length;}
  try{return new TextDecoder('utf-8',{fatal:true,ignoreBOM:false}).decode(bytes);}catch{apiThrow(502,'source_encoding','This source is not valid UTF-8.');}
}

async function apiSchema(db) {
  await db.batch([
    db.prepare('CREATE TABLE IF NOT EXISTS gateway_cache (id TEXT PRIMARY KEY, payload TEXT NOT NULL, expiry INTEGER NOT NULL, touched INTEGER NOT NULL)'),
    db.prepare('CREATE TABLE IF NOT EXISTS gateway_budget (id TEXT PRIMARY KEY, hits INTEGER NOT NULL, expiry INTEGER NOT NULL)'),
  ]);
}

async function apiBudget(db,id,now,width,maximum) {
  const bucket=Math.floor(now/width), expiry=(bucket+1)*width;
  const row=await db.prepare('INSERT INTO gateway_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET hits=hits+1 WHERE hits<? RETURNING hits').bind(id+':'+bucket,expiry,maximum).first();
  if(!row) apiThrow(429,'quota_wait','This source’s shared request allowance is resting. Try again after the indicated delay.',Math.ceil((expiry-now)/1000));
}

async function apiUpstream(plan,env) {
  const target=new URL(plan.target), headers={...plan.headers};
  if(plan.keyName) target.searchParams.set(plan.keyName,plan.secret);
  if(plan.sign){
    const stamp=String(Math.floor(Date.now()/1000));
    const digest=await crypto.subtle.digest('SHA-1',encoder.encode(env.PODCASTINDEX_API_KEY+env.PODCASTINDEX_API_SECRET+stamp));
    headers['X-Auth-Key']=env.PODCASTINDEX_API_KEY; headers['X-Auth-Date']=stamp;
    headers.Authorization=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');
  }
  let current=target, response; const signal=AbortSignal.timeout(plan.timeout||12000);
  try {
  for(let redirect=0;redirect<4;redirect++){
    response=await fetch(current.href,{headers,redirect:'manual',signal});
    if(response.status>=300&&response.status<400){
      await response.body?.cancel();
      if(!plan.feed || redirect===3) apiThrow(502,'source_redirect','The source returned an unsupported redirect.');
      current=apiPublicURL(new URL(response.headers.get('Location')||'',current).href); continue;
    }
    break;
  }
  if(!response.ok){
    const status=response.status;
    await response.body?.cancel();
    if(plan.group==='loc-newspapers' && status>=400 && status!==429){
      const ray=response.headers.get('CF-Ray') || '';
      const reference=/^[a-f0-9]{16}(?:-[A-Z]{3})?$/.test(ray) ? ray : undefined;
      const challenged=response.headers.get('CF-Mitigated')==='challenge';
      console.warn(JSON.stringify({event:'newspaper-source-http',status,reference,challenged}));
      const reason=challenged ? 'The Library of Congress requested browser verification for the server request.'
        : 'The Library of Congress returned HTTP '+status+' for this search.';
      apiThrow(status,'loc_http_'+status,reason+(reference?' Library request ID '+reference+'.':''));
    }
    apiThrow(status===429?429:502,'source_unavailable','The upstream source could not complete this request.',status===429?60:undefined);
  }
  if(plan.group==='loc-newspapers'&&!/application\/(?:[a-z0-9.+-]+\+)?json\b/i.test(response.headers.get('Content-Type')||'')){
    await response.body?.cancel(); apiThrow(502,'invalid_source','The newspaper archive returned a web page instead of JSON.');
  }
  const raw=await apiRead(response,plan.limit);
  if(plan.feed){
    if(/<!DOCTYPE|<!ENTITY/i.test(raw) || !/^\s*(?:<\?xml[^>]*>\s*)?(?:<!--[\s\S]*?-->\s*)*<(?:rss\b|feed\b|rdf:RDF\b)/i.test(raw)) apiThrow(502,'invalid_feed','The URL did not return a supported RSS or Atom feed.');
    return {url:current.href,xml:raw};
  }
  let data; try{data=JSON.parse(raw);}catch{apiThrow(502,'invalid_source','The source returned invalid JSON.');}
  if(plan.group==='loc-newspapers') return newspaperResults(data,plan);
  if(plan.group==='podcast' && (data.status==='false'||data.status===false)) apiThrow(502,'source_unavailable','Podcast Index could not complete this lookup.');
  if(plan.group==='repology'){
    if(!Array.isArray(data) || data.some(x=>!x||typeof x.repo!=='string'||!x.repo||typeof x.version!=='string'||!x.version)) apiThrow(502,'invalid_source','The package source returned an unexpected result.');
    const seen=new Set(); data=data.filter(x=>x&&typeof x==='object').map(x=>Object.fromEntries(['repo','subrepo','srcname','visiblename','version','origversion','summary'].filter(k=>typeof x[k]==='string').map(k=>[k,x[k].slice(0,k==='summary'?2000:300)]))).filter(x=>{const key=JSON.stringify(x);if(seen.has(key))return false;seen.add(key);return true;});
  }
  return data;
  } catch (error) {
    if(plan.group==='loc-newspapers' && !error.api){
      const timedOut=signal.aborted || error.name==='TimeoutError' || error.name==='AbortError';
      apiThrow(timedOut?504:502,timedOut?'loc_timeout':'loc_connection',
        timedOut?'The Library of Congress search timed out. Please try again later.':'The Worker could not read a response from the Library of Congress. Please try again later.');
    }
    if(signal.aborted) apiThrow(504,'source_timeout','The upstream source took too long to respond. Please retry later; saved evidence is unchanged.');
    if(error.api) throw error;
    // Log only a fixed source identifier and error category, never URLs or keys.
    console.warn(JSON.stringify({event:'public-api-source-error',source:plan.group,error:['TypeError','AbortError','TimeoutError'].includes(error.name)?error.name:'Error'}));
    apiThrow(502,'source_network','The upstream source could not be reached. Please retry later.');
  }
}

async function apiHandle(request,env,ctx) {
  try {
    const url=new URL(request.url), origin=request.headers.get('Origin');
    if(origin && origin!==ORIGIN) return apiFailure(403,'origin_denied','Origin is not allowed.');
    if(request.method==='OPTIONS') return {status:204};
    if(['/api/measurebench/','/api/screenradar/','/api/domain-biography/'].some(prefix=>url.pathname.startsWith(prefix))) return await secondBatchApiHandle(request,env,ctx);
    if(url.pathname==='/api/parcelbench/tracking') return await pcTracking(request,env,origin,url);
    if(request.method!=='GET') return apiFailure(405,'method_denied','Use GET for public data requests.');
    if(url.pathname==='/api/browserreceipt/connection') {
      if(origin!==ORIGIN) return apiFailure(403,'origin_denied','Open the connection check on CoolCode.');
      if(url.search) return apiFailure(400,'invalid_query','This connection check takes no query parameters.');
      const cf=request.cf || {};
      const limited=value=>typeof value==='string' ? value.slice(0,200) : null;
      return {headers:{'Cache-Control':'private, no-store'},body:{fetched_at:new Date().toISOString(),data:{
        ip:limited(request.headers.get('CF-Connecting-IP')),
        asn:Number.isSafeInteger(cf.asn) && cf.asn>0 ? cf.asn : null,
        organization:limited(cf.asOrganization),country:limited(cf.country),colo:limited(cf.colo),
        http:limited(cf.httpProtocol),tls:limited(cf.tlsVersion)
      }}};
    }
    if(url.pathname==='/api/status') return {body:{schema:apiVersion,configured:{podcastroute:Boolean(env.PODCASTINDEX_API_KEY&&env.PODCASTINDEX_API_SECRET),channelqueue:Boolean(env.YOUTUBE_API_KEY),recipemath:Boolean(env.FDC_API_KEY),distropilot:true,feedharbour:true,halifaxnext:true,inspectiontrail:true,parcelbench:Boolean(env.CANADAPOST_CLIENT_ID&&env.CANADAPOST_CLIENT_SECRET),corporateghosts:Boolean(env.ISED_CORPORATIONS_API_KEY),screenplaces:Boolean(env.TMDB_READ_ACCESS_TOKEN),planehere:true,planehere_key:Boolean(env.ADSBLOL_API_KEY),screenradar:Boolean(env.TMDB_READ_ACCESS_TOKEN),measurebench:Boolean(env.WOLFRAM_APP_ID),domain_biography:true,newspapers:Boolean(env.LOC_USER_AGENT)}}};
    if(url.pathname.startsWith('/api/halifaxnext/')) return await halifaxApiHandle(request,env,ctx);
    if(url.pathname.startsWith('/api/screenplaces/')) return await screenplacesApiHandle(request,env,ctx);
    if(url.pathname.startsWith('/api/planehere/')) return await planehereApiHandle(request,env,ctx);
    const plan=pcRoute(url,env)||inspectionRoute(url)||apiRoute(url,env), db=env.DB, now=Date.now();
    if(!db) return apiFailure(503,'storage_unavailable','The shared request limiter is unavailable.');
    if(!await allowed(db,request,new Date(now),'tool-api')) return apiFailure(429,'client_wait','Too many requests. Please wait before trying again.',300);
    await apiSchema(db);
    const digest=await crypto.subtle.digest('SHA-256',encoder.encode(apiVersion+'|'+plan.group+'|'+(plan.cacheKey??plan.target.href)));
    const id=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');
    const cached=plan.ttl>0 ? await db.prepare('SELECT payload FROM gateway_cache WHERE id=? AND expiry>?').bind(id,now).first('payload') : null;
    if(cached) return {body:JSON.parse(cached)};
    if(plan.group==='loc-newspapers'){
      const lease=await db.prepare('INSERT INTO gateway_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET expiry=excluded.expiry WHERE expiry<=? RETURNING hits').bind('loc-newspapers-lease',now+4000,now).first();
      if(!lease){
        const until=await db.prepare('SELECT expiry FROM gateway_budget WHERE id=?').bind('loc-newspapers-lease').first('expiry');
        const retry=Math.max(1,Math.ceil((Number(until)-now)/1000));
        return apiFailure(429,'source_pacing',retry>4?'The Library has paused requests. Please try again later.':'Please wait a few seconds between newspaper searches.',retry);
      }
    }
    if(plan.group==='repology'){
      // Atomic sliding lease across ALL Worker instances; Cache API alone is only per-PoP.
      const lease=await db.prepare('INSERT INTO gateway_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET expiry=excluded.expiry WHERE expiry<=? RETURNING hits').bind('repology-lease',now+1100,now).first();
      if(!lease) return apiFailure(429,'source_pacing','The package source permits one request per second. Please retry shortly.',2);
    }
    await apiBudget(db,plan.group,now,plan.window,plan.maximum);
    let data;
    try {data=await (plan.pc?pcUpstream(plan,env):plan.inspection?inspectionUpstream(plan):apiUpstream(plan,env));}
    catch(error){
      if(plan.group==='loc-newspapers' && error.api && error.status===429){
        await db.prepare('INSERT INTO gateway_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET expiry=MAX(expiry,excluded.expiry)').bind('loc-newspapers-lease',Date.now()+3600000).run();
        apiThrow(429,'source_cooldown','The Library has paused requests. Try again in an hour.',3600);
      }
      throw error;
    }
    const captured=Date.now(), result={fetched_at:new Date(captured).toISOString(),data}, payload=JSON.stringify(result);
    await db.prepare('DELETE FROM gateway_budget WHERE expiry<=?').bind(captured).run();
    // <=256 records; ordinary responses <=500 KB, package evidence <=1 MB.
    // Popular projects such as PHP exceed 500 KB after lossless field selection.
    if(plan.ttl>0 && encoder.encode(payload).byteLength<=(plan.group==='repology'?1000000:500000)) await db.batch([
      db.prepare('DELETE FROM gateway_cache WHERE expiry<=?').bind(captured),
      db.prepare('DELETE FROM gateway_budget WHERE expiry<=?').bind(captured),
      db.prepare('INSERT INTO gateway_cache(id,payload,expiry,touched) VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,expiry=excluded.expiry,touched=excluded.touched').bind(id,payload,captured+plan.ttl*1000,captured),
      db.prepare('DELETE FROM gateway_cache WHERE id IN (SELECT id FROM gateway_cache ORDER BY touched DESC,id DESC LIMIT -1 OFFSET 256)'),
    ]);
    return {body:result};
  }catch(e){
    if(e.api) return apiFailure(e.status,e.code,e.message,e.retry);
    return apiFailure(503,'temporarily_unavailable','The source or shared request service is temporarily unavailable. Your saved workspace is unchanged.');
  }
}


// Fixed-source, bounded GTFS-realtime relay. Parsing runs in Halifax Next's browser worker.
// This avoids large protobuf / JSON / gzip transformations in the edge CPU budget.
const halifaxFeeds = Object.freeze({vehicles:'Vehicle/VehiclePositions.pb',trips:'TripUpdate/TripUpdates.pb',alerts:'Alert/Alerts.pb'});
function halifaxBoundedStream(body,length,limit=5000000){
 if(!Number.isSafeInteger(length)||length<=0||length>limit)throw new Error('Invalid Halifax feed length');
 // Native stream enforces both short and excess bodies without JavaScript per chunk.
 return body.pipeThrough(new FixedLengthStream(length));
}
async function halifaxApiHandle(request,env,ctx) {
  const origin=request.headers.get('Origin');if(origin&&origin!==ORIGIN)return apiFailure(403,'origin','This origin is not allowed.');
  if(request.method==='OPTIONS')return {status:204};if(request.method!=='GET')return apiFailure(405,'method','Use GET.');
  try {
    const url=new URL(request.url);if(url.pathname!=='/api/halifaxnext/realtime')return apiFailure(404,'route','Unknown Halifax API route.');
    const p=apiParams(url,['feed','stop']),feed=p('feed',/^(vehicles|trips|alerts)$/,'trips'),stop=p('stop',/^[A-Za-z0-9_.-]{0,64}$/,'');
    if(feed==='trips'&&!stop)return apiFailure(400,'parameter','Select a stop for departure updates.');
    const db=env.DB;if(!db)return apiFailure(503,'configuration','The transit cache is not configured.');
    const now=Date.now();if(!await allowed(db,request,new Date(now),'tool-api'))return apiFailure(429,'rate_limit','Please try again shortly.',300);
    await apiSchema(db);
    const cache=typeof caches!=='undefined'?caches.default:null;
    const cacheRequest=new Request(new URL('/api/halifaxnext/cache/raw-v1/'+feed,url.origin).href);
    const cached=cache?await cache.match(cacheRequest):null;
    if(cached)return {rawResponse:cached};
    await apiBudget(db,'halifax:'+feed,now,86400000,4000);
    // IIS requires its actual protocol-buffer MIME; Workers supports manual, not error, redirects.
    const response=await fetch('https://gtfs.halifax.ca/realtime/'+halifaxFeeds[feed],{headers:{'User-Agent':apiUA,Accept:'application/protocol-buffer,application/x-protobuf,application/octet-stream','Accept-Encoding':'identity'},redirect:'manual',signal:AbortSignal.timeout(12000)});
    if(!response.ok){await response.body?.cancel();return apiFailure(502,'source','Halifax Transit is temporarily unavailable. Scheduled times remain available.');}
    const size=response.headers.get('Content-Length'),encoding=response.headers.get('Content-Encoding');
    if(encoding&&encoding.toLowerCase()!=='identity'){await response.body?.cancel();return apiFailure(502,'source','Halifax Transit returned an unsupported transport encoding.');}
    if(/^(?:text\/|application\/(?:json|xml|xhtml))/i.test(response.headers.get('Content-Type')||'')){await response.body?.cancel();return apiFailure(502,'source','Halifax Transit did not return a realtime feed.');}
    if(!response.body||size===null||!/^\d+$/.test(size)||!Number.isSafeInteger(Number(size))||Number(size)<=0||Number(size)>5000000){await response.body?.cancel();return apiFailure(502,'source','Halifax Transit returned an invalid or oversized response length.');}
    const raw=new Response(halifaxBoundedStream(response.body,Number(size)),{headers:{'Content-Type':'application/x-protobuf','Cache-Control':'public, max-age=30','X-CoolCode-Fetched-At':new Date(now).toISOString()}});
    if(cache&&ctx?.waitUntil)ctx.waitUntil(cache.put(cacheRequest,raw.clone()).catch(()=>{}));
    return {rawResponse:raw};
  } catch(e){return e&&e.api?apiFailure(e.status,e.code,e.message,e.retry):apiFailure(503,'source','Live transit information is temporarily unavailable. Use the labelled scheduled times.');}
}


// Bounded, read-only adapter for Nova Scotia’s public ASP.NET inspection search.
// Source HTML is never inserted into the page. Only bounded text fields are exposed.
function inspectionText(value='') {
  return String(value).replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,'').replace(/<[^>]*>/g,' ').replace(/&(#x[\da-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi,(_,e)=>{const known={amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' '};if(known[e.toLowerCase()]!==undefined)return known[e.toLowerCase()];const n=e[1].toLowerCase()==='x'?parseInt(e.slice(2),16):parseInt(e.slice(1),10);return n>0&&n<=0x10ffff?String.fromCodePoint(n):'';}).replace(/\s+/g,' ').trim();
}
function inspectionSpan(html,id){return inspectionText(html.match(new RegExp('<span\\b[^>]*\\bid="'+id+'"[^>]*>([\\s\\S]*?)<\\/span>','i'))?.[1]||'');}
function inspectionParseSearch(html){
  const date=inspectionSpan(html,'lblLastUploadDateTime'),countText=inspectionSpan(html,'LblResultsCount');
  if(!date || !/^\d+$/.test(countText))throw new Error('Unrecognized inspection search response');
  const rows=[...html.matchAll(/<tr\b[^>]*class="ResultsTableRow[^"]*"[^>]*>([\s\S]*?)<\/tr>/gi)].map(m=>{const link=m[1].match(/href="Details\.aspx\?Id1=(\d+)"[^>]*>([\s\S]*?)<\/a>/i);const address=m[1].match(/<td\b[^>]*class="ResultsTableAddress"[^>]*>([\s\S]*?)<\/td>/i);if(!link||!address)throw new Error('Unrecognized establishment row');return {id:link[1],name:inspectionText(link[2]),address:inspectionText(address[1])};});
  if(rows.length!==Number(countText)||new Set(rows.map(x=>x.id)).size!==rows.length)throw new Error('Incomplete inspection results');
  return {source_updated:date,total:rows.length,truncated:rows.length>200,establishments:rows.slice(0,200)};
}
function inspectionParseReport(html,id){
  const name=inspectionSpan(html,'LblEstablishmentName'),address=inspectionSpan(html,'LblAddress');
  if(!name||!address||!html.includes('InspectionTable'))throw new Error('Unrecognized inspection report');
  const advisoryHTML=html.match(/<table\b[^>]*id="BoilWaterAdvisoryTable"[^>]*>([\s\S]*?)<\/table>/i)?.[1]||'';
  const advisories=[...advisoryHTML.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)].flatMap(m=>{const cells=[...m[1].matchAll(/<td\b[^>]*>([\s\S]*?)<\/td>/gi)].map(c=>inspectionText(c[1]));return cells.length===2?[{issued:cells[0]||null,removed:cells[1]||null}]:[];});
  const positions=[...html.matchAll(/<span\b[^>]*class="LabelInspectionDateStatus"[^>]*>Date Inspected:\s*([^<]*)<\/span>/gi)];
  const inspections=positions.map((m,i)=>{const block=html.slice(m.index,positions[i+1]?.index||html.indexOf('Disclaimer Footer'));const findings=[...block.matchAll(/<span\b[^>]*class="LabelInspectionText"[^>]*>([\s\S]*?)<\/span>\s*<\/td>\s*<td[^>]*>\s*<a\b[^>]*class="LinkInspectionText"[^>]*>([\s\S]*?)<\/a>[\s\S]*?<span\b[^>]*class="LabelInspectionHeader"[^>]*>Remedy<\/span>[\s\S]*?<span\b[^>]*class="LabelInspectionText"[^>]*>([\s\S]*?)<\/span>/gi)].map(f=>({finding:inspectionText(f[1]),status:inspectionText(f[2]),remedy:inspectionText(f[3])}));
    const summary=inspectionText(block.match(/class="DetailsCellOuter"[^>]*>\s*<span[^>]*>([\s\S]*?)<\/span>/i)?.[1]||'');
    // Preserve closure/warning annotations beside the inspection date as published.
    const annotation=inspectionText(block.match(/<\/span><\/td><td[^>]*>([\s\S]*?)<\/td>/i)?.[1]||'');
    if((block.match(/class="LinkInspectionText"/g)||[]).length!==findings.length)throw new Error('Unrecognized findings layout');
    return {date:inspectionText(m[1]),annotation,summary,findings};});
  if(!inspections.length)throw new Error('Report has no recognized inspection dates');
  return {id,name,address,advisories,inspections};
}

function inspectionRoute(url) {
  if(!url.pathname.startsWith('/api/inspectiontrail/'))return null;
  if(!['/api/inspectiontrail/search','/api/inspectiontrail/report'].includes(url.pathname))apiThrow(404,'unknown_endpoint','Unknown inspection endpoint.');
  const p=apiParams(url,['q','town','address','mode','id']);
  const query={q:p('q',/^[^\x00-\x1f]{0,120}$/u,''),town:p('town',/^[^\x00-\x1f]{0,100}$/u,''),address:p('address',/^[^\x00-\x1f]{0,120}$/u,''),mode:p('mode',/^(search|current-closures|closures-year|current-warnings|warnings-year)$/,'search')};
  if(query.mode==='search' && Math.max(query.q.length,query.town.length,query.address.length)<2)apiThrow(400,'invalid_parameter','Enter at least two characters of a name, community or street.');
  const report=url.pathname.endsWith('/report');
  if(report)query.id=p('id',/^\d{1,12}$/);else if(url.searchParams.has('id'))apiThrow(400,'invalid_parameter','Search does not accept an ID.');
  return {target:new URL('https://novascotia.ca/nse/food-protection/reports/Request.aspx'),cacheKey:'inspection-v1|'+JSON.stringify(query),group:'inspection',window:86400000,maximum:1500,ttl:300,limit:2000000,timeout:30000,inspection:true,inspectionQuery:query};
}
async function inspectionUpstream(plan) {
  const signal=AbortSignal.timeout(plan.timeout),jar=new Map();
  async function read(url,body){
    const headers={'Accept':'text/html','User-Agent':apiUA};if(jar.size)headers.Cookie=[...jar].map(([k,v])=>k+'='+v).join('; ');
    if(body)headers['Content-Type']='application/x-www-form-urlencoded';
    const response=await fetch(url,{method:body?'POST':'GET',body:body?.toString(),headers,redirect:'manual',signal});
    if(!response.ok){await response.body?.cancel();apiThrow(502,'inspection_source_unavailable','The provincial inspection search is unavailable. Open the official source or try again later.');}
    // Anonymous ASP.NET session cookies never leave this one source request chain.
    const cookie=response.headers.get('Set-Cookie')||'';
    for(const m of cookie.matchAll(/(?:^|,\s*)([A-Za-z0-9_.-]{1,80})=([^;,\s]{1,2048})/gi))jar.set(m[1],m[2]);
    return apiRead(response,plan.limit);
  }
  try {
    const initial=await read(plan.target.href);const fields=new URLSearchParams();
    for(const m of initial.matchAll(/<input\b[^>]*>/gi)){
      const attrs=Object.fromEntries([...m[0].matchAll(/([\w]+)="([^"]*)"/g)].map(a=>[a[1],a[2]]));
      if(attrs.type==='hidden' && ['__VIEWSTATE','__VIEWSTATEGENERATOR','__EVENTVALIDATION'].includes(attrs.name))fields.set(attrs.name,inspectionText(attrs.value));
    }
    if(!fields.has('__VIEWSTATE')||!fields.has('__EVENTVALIDATION'))apiThrow(502,'inspection_source_changed','The provincial search format has changed. Use the official search while this adapter is updated.');
    const q=plan.inspectionQuery;
    fields.set('TxtEstablishmentName',q.q);fields.set('TxtCity',q.town);fields.set('TxtEstablishmentStreet',q.address);fields.set('TxtEstablishmentStreetNo','');
    for(const from of ['From','To'])for(const part of ['Month','Day','Year'])fields.set('Drop'+from+part,'');
    const buttons={search:['BttnSubmit','Submit'],'current-closures':['BttnClosuresCurrent','Current Closures'],'closures-year':['BttnClosuresPastYear','Closures in Past 12 Months'],'current-warnings':['BttnWarningsCurrent','Current Warnings'],'warnings-year':['BttnWarningsPastYear','Warnings in Past 12 Months']};
    const [button,value]=buttons[q.mode];fields.set(button,value);const result=inspectionParseSearch(await read(plan.target.href,fields));
    if(q.id){
      if(!result.establishments.some(row=>row.id===q.id))apiThrow(404,'inspection_not_found','That establishment is not in this search. Refine the name or community and try again.');
      return {source_updated:result.source_updated,report:inspectionParseReport(await read(new URL('Details.aspx?Id1='+q.id,plan.target).href),q.id)};
    }
    return result;
  }catch(e){if(e.api)throw e;if(signal.aborted)apiThrow(504,'source_timeout','The provincial inspection search took too long. Try again later.');apiThrow(502,'inspection_source_changed','The provincial search could not be read. Use the official search while this adapter is checked.');}
}


// Inlined after gateway.js. Fixed-host, read-only Canada Post and federal registry adapters.
// OAuth credentials and bearer tokens never enter the shared response cache or logs.
// Contracts reviewed 2026-11-25: Canada Post portal downloads /4632/document (Rating),
// /4631/document (Post Office); https://api.ised-isde.canada.ca/swagger/spec/corporation-en.json
const pcBase = 'https://api.canadapost-postescanada.ca/prod/devportal-portaildesdeveloppeurs/';
const pcPostal = /^[ABCEGHJ-NPRSTVXY]\d[ABCEGHJ-NPRSTV-Z]\d[ABCEGHJ-NPRSTV-Z]\d$/;
let pcToken = null; // Bounded, isolate-local token; expiry and credential fingerprint checked on every use.
const pcText = (v,n=300) => typeof v==='string'?v.slice(0,n):'';
const pcNumber = v => typeof v==='number' && Number.isFinite(v)?v:null;
const pcDate = v => typeof v==='string' && /^\d{4}-\d\d-\d\d(?:T.*)?$/.test(v) && Number.isFinite(Date.parse(v))?v.slice(0,10):null;

function pcRoute(url,env) {
  const path=url.pathname;
  if(!path.startsWith('/api/parcelbench/') && !path.startsWith('/api/corporateghosts/')) return null;
  const plan={pc:true,ttl:0,limit:1_000_000,group:'canadapost',window:60000,maximum:80,headers:{Accept:'application/json','Accept-Language':'en-CA','User-Agent':apiUA}};
  let p;
  if(path==='/api/corporateghosts/corporation') {
    p=apiParams(url,['id']); const id=p('id',/^\d{1,12}$/);
    plan.target=new URL('https://apigateway-passerelledapi.ised-isde.canada.ca/cc/api/v1/corporations/'+id);
    for(const include of ['directors','filings','isc']) plan.target.searchParams.append('include',include);
    if(!env.ISED_CORPORATIONS_API_KEY) apiThrow(503,'not_configured','Current federal records are awaiting the site API configuration. Snapshot search remains available.');
    Object.assign(plan,{group:'ised-corporations',maximum:50,ttl:300,kind:'corporation',id});
  } else if(path==='/api/parcelbench/rates') {
    p=apiParams(url,['origin','destination','weight','length','width','height','mailingDate']);
    const postal=key=>p(key,pcPostal), number=(key,min,max,precision)=>{
      const raw=p(key,new RegExp('^\\d{1,3}(?:\\.\\d{1,'+precision+'})?$')), value=Number(raw);
      if(value<min||value>max)apiThrow(400,'invalid_parameter','Check the '+key+' value.');return value;
    };
    const dimensions=[number('length',0.1,200,1),number('width',0.1,200,1),number('height',0.1,200,1)].sort((a,b)=>b-a);
    const mailingDate=p('mailingDate',/^\d{4}-\d\d-\d\d$/), day=Date.parse(mailingDate+'T00:00:00Z'), now=Date.now();
    if(!Number.isFinite(day)||new Date(day).toISOString().slice(0,10)!==mailingDate||day<now-2*86400000||day>now+366*86400000)apiThrow(400,'invalid_parameter','Choose a real mailing date from today through the coming year.');
    plan.body=JSON.stringify({quoteType:'counter',expectedMailingDate:mailingDate,originPostalCode:postal('origin'),destination:{domestic:{postalCode:postal('destination')}},parcelCharacteristics:{weight:number('weight',0.001,30,3),dimensions:{length:dimensions[0],width:dimensions[1],height:dimensions[2]}}});
    plan.method='POST';plan.kind='rates';plan.target=new URL(pcBase+'rating/v1/prices');plan.cacheKey=plan.body;
  } else if(path==='/api/parcelbench/offices') {
    p=apiParams(url,['postal']);plan.kind='offices';plan.target=new URL(pcBase+'postoffice/v1/post-offices');
    plan.target.searchParams.set('postal-code',p('postal',pcPostal));plan.target.searchParams.set('maximum','10');plan.target.searchParams.set('d2po','false');
  } else if(path==='/api/parcelbench/office') {
    p=apiParams(url,['id']);plan.kind='office';plan.target=new URL(pcBase+'postoffice/v1/post-offices/'+p('id',/^\d{1,12}$/)+'/details');
  } else apiThrow(404,'unknown_endpoint','Unknown parcel or corporation endpoint.');
  if(plan.group==='canadapost'&&(!env.CANADAPOST_CLIENT_ID||!env.CANADAPOST_CLIENT_SECRET))apiThrow(503,'not_configured','Canada Post lookup is awaiting the site API configuration.');
  return plan;
}

async function pcPace(db,group) {
  // Shared lease prevents bursts across Worker instances, not merely in one isolate.
  for(let attempt=0;attempt<2;attempt++) {
    const now=Date.now(), spacing=group==='canadapost'?300:1100;
    const row=await db.prepare('INSERT INTO gateway_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET expiry=excluded.expiry WHERE expiry<=? RETURNING hits').bind(group+'-lease',now+spacing,now).first();
    if(row)return;
    if(!attempt)await new Promise(resolve=>setTimeout(resolve,spacing));
  }
  apiThrow(429,'source_pacing','This source is busy. Please retry in a moment.',2);
}

async function pcFetch(target,options,plan,env) {
  await pcPace(env.DB,plan.group);
  const signal=AbortSignal.timeout(15000);
  try {
    const response=await fetch(target,{...options,redirect:'manual',signal});
    if(!response.ok){
      await response.body?.cancel();
      if(response.status===404)apiThrow(404,'record_not_found','The source did not find this record. Check the number in the official register.');
      if(response.status===429)apiThrow(429,'source_busy','The source has asked us to pause. Please retry later.',60);
      if(response.status===401||response.status===403)apiThrow(503,'source_authentication','The source did not accept this service’s API credentials or subscription. The site operator needs to check its production API configuration.');
      if(response.status===400||response.status===422)apiThrow(400,'source_input','The source could not quote these inputs. Check the postal codes, mailing date, weight and dimensions; some services have package limits.');
      apiThrow(502,'source_unavailable','The source could not complete this request. Please retry later.');
    }
    const raw=await apiRead(response,plan.limit);
    try{return JSON.parse(raw);}catch{apiThrow(502,'invalid_source','The source returned an unexpected response.');}
  } catch(error) {
    if(error.api)throw error;
    apiThrow(signal.aborted?504:502,signal.aborted?'source_timeout':'source_network','The source could not be reached in time. Please retry later.');
  }
}

async function pcBearer(plan,env) {
  const fingerprint=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(env.CANADAPOST_CLIENT_ID+'\0'+env.CANADAPOST_CLIENT_SECRET))),b=>b.toString(16).padStart(2,'0')).join('');
  if(pcToken?.fingerprint===fingerprint&&pcToken.expires>Date.now()+60000)return pcToken.value;
  const body=new URLSearchParams({grant_type:'client_credentials',scope:'merchant',client_id:env.CANADAPOST_CLIENT_ID,client_secret:env.CANADAPOST_CLIENT_SECRET});
  const token=await pcFetch(pcBase+'cpc-api-native-oauth-provider/oauth2/token',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded'},body}, {...plan,limit:20000},env);
  if(typeof token.access_token!=='string'||token.access_token.length>16000||!/^\S+$/.test(token.access_token)||!/^Bearer$/i.test(token.token_type||'')||!Number.isFinite(Number(token.expires_in))||Number(token.expires_in)<=0)apiThrow(502,'source_authentication','The source returned an invalid authorization response.');
  pcToken={fingerprint,value:token.access_token,expires:Date.now()+Math.min(Number(token.expires_in),28800)*1000};
  return pcToken.value;
}

function pcRates(data) {
  if(!Array.isArray(data)||data.length>50)apiThrow(502,'invalid_source','The quote source returned an unexpected result.');
  return {quoteType:'counter',currency:'CAD',quotes:data.map(x=>{
    if(!x||typeof x.serviceCode!=='string'||typeof x.serviceName!=='string'||pcNumber(x.priceDetails?.due)===null)apiThrow(502,'invalid_source','The quote source returned an incomplete price.');
    const p=x.priceDetails,s=x.serviceStandard||{};
    return {code:pcText(x.serviceCode,40),name:pcText(x.serviceName),total:pcNumber(p.due),base:pcNumber(p.base),taxes:Object.fromEntries(['gst','pst','hst'].filter(k=>p.taxes?.[k]).map(k=>[k,pcNumber(p.taxes[k].amt)])),adjustments:(p.adjustments||[]).slice(0,20).map(a=>({name:pcText(a.adjustmentName),cost:pcNumber(a.adjustmentCost)})),options:(p.options||[]).slice(0,20).map(a=>({name:pcText(a.optionName),cost:pcNumber(a.optionPrice)})),cubedWeight:pcNumber(x.weightDetails?.cubedWeight),expectedDeliveryDate:pcDate(s.expectedDeliveryDate),expectedTransitTime:pcNumber(s.expectedTransitTime),guaranteedDelivery:typeof s.guaranteedDelivery==='boolean'?s.guaranteedDelivery:null};
  })};
}
function pcOfficeDay(day) {
  // Only canonical integer strings are equivalent to the documented day numbers.
  if(typeof day==='string' && /^[1-7]$/.test(day))return Number(day);
  return Number.isInteger(day)&&day>=1&&day<=7?day:null;
}
function pcOffice(x) {
  if(!x||!/^\d{1,12}$/.test(String(x.officeId))||!x.address)apiThrow(502,'invalid_source','The post office source returned an incomplete record.');
  const a=x.address,latitude=Number(a.latitude),longitude=Number(a.longitude);
  const coordinates=Number.isFinite(latitude)&&latitude>=40&&latitude<=90&&Number.isFinite(longitude)&&longitude>=-150&&longitude<=-50?{latitude,longitude}:null;
  // Use a validated fixed-host detail link ID when supplied, preserving leading zeros.
  let id=String(x.officeId);try{const link=new URL(x.link?.href);if(link.origin===new URL(pcBase).origin){const match=link.pathname.match(/\/post-offices\/(\d{1,12})\/details$/);if(match)id=match[1];}}catch{}
  return {id,name:pcText(x.name),location:pcText(x.location),address:[a.officeAddress,a.city,a.province,a.postalCode].filter(v=>typeof v==='string').map(v=>v.slice(0,150)).join(', '),coordinates,distance:pcNumber(x.distance),hours:Array.isArray(x.hoursList)?x.hoursList.slice(0,7).filter(h=>h&&pcOfficeDay(h.day)!==null&&Array.isArray(h.time)).map(h=>({day:pcOfficeDay(h.day),times:h.time.slice(0,4).filter(t=>typeof t==='string'&&/^(?:[01]?\d|2[0-3]):[0-5]\d$/.test(t))})):null};
}
function pcCorporation(x) {
  if(!x||!/^\d{1,12}$/.test(String(x.corporationNumber))||!x.corporateName||typeof x.corporateName.legalName!=='string')apiThrow(502,'invalid_source','The federal source returned an incomplete record.');
  const filings=Array.isArray(x.filingHistory)?x.filingHistory.slice(0,500).map(f=>({type:pcText(f.recordType,100),receivedDate:pcDate(f.receivedDate),effectiveDate:pcDate(f.effectiveDate),year:pcNumber(f.year),legalName:pcText(f.corporateName?.legalName)})):null;
  const statements=Array.isArray(x.controlStatements)?x.controlStatements.slice(0,500):null;
  return {id:String(x.corporationNumber),legalName:pcText(x.corporateName.legalName,500),alternateLegalName:pcText(x.corporateName.alternateLegalName,500),status:pcText(x.status,100),statusDetail:pcText(x.statusDetail,200),legislation:pcText(x.legislation,100),corporationType:pcText(x.declaredCorporationType,150),anniversaryDate:pcDate(x.anniversaryDate),locality:[x.registeredOffice?.city,x.registeredOffice?.subdivision,x.registeredOffice?.country].filter(v=>typeof v==='string').map(v=>v.slice(0,150)).join(', '),annualReturns:Array.isArray(x.annualReturnCompliance)?x.annualReturnCompliance.slice(0,100).map(a=>({year:pcNumber(a.year),status:pcText(a.status,80)})):null,directors:Array.isArray(x.board?.directors)?x.board.directors.slice(0,200).map(d=>({name:[pcText(d.givenName),pcText(d.familyName)].filter(Boolean).join(' '),changeType:pcText(d.changeType,80)})):null,directorsTruncated:Array.isArray(x.board?.directors)&&x.board.directors.length>200,filings,filingsTruncated:Array.isArray(x.filingHistory)&&x.filingHistory.length>500,controlStatements:statements===null?null:statements.filter(s=>s.recordType==='person').map(s=>({date:pcDate(s.statementDate),status:pcText(s.recordStatus,50),personType:pcText(s.recordDetails?.personType,80),names:Array.isArray(s.recordDetails?.names)?s.recordDetails.names.slice(0,10).map(n=>pcText(n.fullName,300)||[pcText(n.givenName),pcText(n.familyName)].filter(Boolean).join(' ')).filter(Boolean):[]})),controlStatementsTruncated:Array.isArray(x.controlStatements)&&x.controlStatements.length>500};
}
async function pcUpstream(plan,env) {
  const headers={...plan.headers};
  if(plan.group==='canadapost')headers.Authorization='Bearer '+await pcBearer(plan,env);
  else headers.user_key=env.ISED_CORPORATIONS_API_KEY;
  if(plan.body)headers['Content-Type']='application/json';
  let data;
  try{data=await pcFetch(plan.target.href,{method:plan.method||'GET',headers,...(plan.body?{body:plan.body}:{})},plan,env);}catch(error){if(plan.group==='canadapost'&&error.code==='source_authentication')pcToken=null;throw error;}
  if(plan.kind==='rates')return pcRates(data);
  if(plan.kind==='office')return pcOffice(data);
  if(plan.kind==='offices'){if(!Array.isArray(data)||data.length>50)apiThrow(502,'invalid_source','The post office source returned an unexpected result.');return {offices:data.slice(0,10).map(pcOffice)};}
  const corporation=pcCorporation(data);
  if(Number(corporation.id)!==Number(plan.id))apiThrow(502,'invalid_source','The federal source returned a different corporation number.');
  return corporation;
}

// Only expose tracking dates and event text. Raw tracking responses contain references,
// postal codes and delivery details outside the scope of this consumer tool.
function pcPublicTracking(record) {
  if (!record || !Array.isArray(record.significantEvents) || record.significantEvents.length > 500) {
    apiThrow(502,'invalid_source','Canada Post returned an unrecognized tracking response.');
  }
  return {
    service: pcText(record.serviceName,100),
    expected: pcDate(record.changedExpectedDate) || pcDate(record.expectedDeliveryDate),
    events: record.significantEvents.slice(0,100)
      .filter(event => event && typeof event.eventDescription === 'string')
      .map(event => ({
        date: pcDate(event.eventDate),
        time: /^\d\d:\d\d:\d\d$/.test(event.eventTime) ? event.eventTime : '',
        zone: pcText(event.eventTimeZone,12),
        description: pcText(event.eventDescription,240),
        city: pcText(event.eventSite,100),
        province: pcText(event.eventProvince,8)
      }))
  };
}

async function pcTracking(request,env,origin,url) {
  if (origin !== ORIGIN) return apiFailure(403,'origin_denied','Open parcel tracking on CoolCode.');
  if (request.method !== 'POST') return apiFailure(405,'method_denied','Submit the tracking form.');
  if (url.search || (request.headers.get('Content-Type') || '').split(';')[0].trim() !== 'application/json') {
    return apiFailure(400,'invalid_query','Submit a tracking number in the form.');
  }
  if (env.CANADAPOST_PUBLIC_TRACKING !== 'enabled' || !env.CANADAPOST_CLIENT_ID || !env.CANADAPOST_CLIENT_SECRET) {
    return apiFailure(503,'tracking_unavailable','View the latest events directly at Canada Post.');
  }
  let payload;
  try { payload = JSON.parse(await apiRead(request,160)); }
  catch { return apiFailure(400,'invalid_query','Enter a single tracking number.'); }
  const id = payload?.number;
  if (!payload || Object.keys(payload).length !== 1 || typeof id !== 'string' || !/^(?:[A-Z0-9]{12,13}|\d{15,16})$/.test(id)) {
    return apiFailure(400,'invalid_parameter','Check the tracking or delivery notice number.');
  }
  const plan = {group:'canadapost',limit:160000};
  if (!env.DB) return apiFailure(503,'storage_unavailable','Tracking is temporarily unavailable.');
  const now = Date.now();
  if (!await allowed(env.DB,request,new Date(now),'tool-api')) return apiFailure(429,'client_wait','Please wait before checking another parcel.',300);
  await apiSchema(env.DB);
  await apiBudget(env.DB,'canadapost',now,60000,80);
  const token = await pcBearer(plan,env);
  const resource = /^\d{15}$/.test(id) ? 'dncs' : 'pins';
  try {
    const record = await pcFetch(pcBase+'tracking/v1/'+resource+'/'+id+'/details',
      {method:'GET',headers:{Accept:'application/json','Accept-Language':'en-CA',Authorization:'Bearer '+token}},plan,env);
    return {headers:{'Cache-Control':'private, no-store'},body:{fetched_at:new Date().toISOString(),data:pcPublicTracking(record)}};
  } catch (error) {
    if (error.code === 'source_authentication') pcToken = null;
    if (error.code === 'record_not_found' || error.code === 'source_input') return apiFailure(404,'tracking_unknown','No tracking events were found for that number.');
    throw error;
  }
}


/* Screen Places TMDb lookup. Root can inline this module after removing export keywords.
   Dispatch /api/screenplaces/* before the ordinary shared apiRoute plan.
   Returns the shared gateway's {status, body, headers} response descriptor. */
const spApiError = (status, code, message, retry) => ({
  status,
  body: { error: { code, message } },
  headers: retry ? { "Retry-After": String(retry) } : {},
});
function screenplacesRoute(url) {
  if (url.pathname !== "/api/screenplaces/title") return null;
  const id = url.searchParams.get("wikidata");
  if (
    !id ||
    !/^Q[1-9]\d{0,11}$/.test(id) ||
    [...url.searchParams.keys()].some((k) => k !== "wikidata") ||
    url.searchParams.getAll("wikidata").length !== 1
  )
    throw new Error("invalid_query");
  return {
    id,
    target: `https://api.themoviedb.org/3/find/${id}?external_source=wikidata_id&language=en-US`,
  };
}
function screenplacesNormalize(payload) {
  let type = "movie",
    item = payload?.movie_results?.[0];
  if (!item) {
    type = "tv";
    item = payload?.tv_results?.[0];
  }
  if (!item) return null;
  if (!Number.isInteger(item.id) || item.id <= 0)
    throw new Error("invalid_source");
  const image =
    typeof item.poster_path === "string" &&
    /^\/[A-Za-z0-9_-]+\.(jpg|png|webp)$/.test(item.poster_path)
      ? `https://image.tmdb.org/t/p/w342${item.poster_path}`
      : null;
  const rating = Number(item.vote_average),
    votes = Number(item.vote_count);
  return {
    id: item.id,
    type,
    title: String(item.title || item.name || "").slice(0, 300),
    overview: String(item.overview || "").slice(0, 5000),
    poster_url: image,
    rating:
      Number.isFinite(rating) && rating >= 0 && rating <= 10 ? rating : null,
    rating_count: Number.isSafeInteger(votes) && votes >= 0 ? votes : 0,
    release_date: String(item.release_date || item.first_air_date || "").slice(
      0,
      10,
    ),
    tmdb_url: `https://www.themoviedb.org/${type}/${item.id}`,
  };
}
async function spApiJson(response) {
  if (Number(response.headers.get("Content-Length") || 0) > 524288)
    throw new Error("oversize");
  if (!/application\/json/i.test(response.headers.get("Content-Type") || ""))
    throw new Error("invalid_source");
  const reader = response.body.getReader(),
    parts = [];
  let size = 0;
  try {
    while (true) {
      const r = await reader.read();
      if (r.done) break;
      size += r.value.byteLength;
      if (size > 524288) {
        await reader.cancel();
        throw new Error("oversize");
      }
      parts.push(r.value);
    }
  } finally {
    reader.releaseLock();
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const p of parts) {
    bytes.set(p, offset);
    offset += p.byteLength;
  }
  return JSON.parse(
    new TextDecoder("utf-8", { fatal: true, ignoreBOM: false }).decode(bytes),
  );
}
async function spApiBudget(db, key, now, width, max) {
  const start = Math.floor(now / width) * width,
    expiry = start + width;
  const row = await db
    .prepare(
      "INSERT INTO screenplaces_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET hits=CASE WHEN expiry<=? THEN 1 ELSE hits+1 END, expiry=excluded.expiry RETURNING hits",
    )
    .bind(key, expiry, now)
    .first();
  return row?.hits <= max;
}
async function screenplacesApiHandle(request, env, ctx) {
  const origin = request.headers.get("Origin");
  if (origin && origin !== "https://coolcode.ca")
    return spApiError(403, "origin_denied", "Origin is not allowed.");
  if (request.method === "OPTIONS") return { status: 204 };
  if (request.method !== "GET")
    return spApiError(405, "method_denied", "Use GET for title lookups.");
  let plan;
  try {
    plan = screenplacesRoute(new URL(request.url));
  } catch {
    return spApiError(
      400,
      "invalid_query",
      "Provide one Wikidata item ID, such as Q2744.",
    );
  }
  if (!plan)
    return spApiError(
      404,
      "unknown_route",
      "This Screen Places endpoint does not exist.",
    );
  if (!env.TMDB_READ_ACCESS_TOKEN)
    return spApiError(
      503,
      "not_configured",
      "Film details are not configured yet. The filming-location catalogue is still available.",
    );
  const db = env.DB;
  if (!db)
    return spApiError(
      503,
      "storage_unavailable",
      "The title cache is temporarily unavailable.",
    );
  try {
    await db.batch([
      db.prepare(
        "CREATE TABLE IF NOT EXISTS screenplaces_cache(id TEXT PRIMARY KEY,payload TEXT NOT NULL,expiry INTEGER NOT NULL)",
      ),
      db.prepare(
        "CREATE TABLE IF NOT EXISTS screenplaces_budget(id TEXT PRIMARY KEY,hits INTEGER NOT NULL,expiry INTEGER NOT NULL)",
      ),
      db.prepare(
        "CREATE TABLE IF NOT EXISTS screenplaces_salts(day TEXT PRIMARY KEY,secret TEXT NOT NULL)",
      ),
    ]);
    const now = Date.now(),
      day = new Date(now).toISOString().slice(0, 10);
    await db.batch([
      db.prepare("DELETE FROM screenplaces_cache WHERE expiry<=?").bind(now),
      db.prepare("DELETE FROM screenplaces_budget WHERE expiry<=?").bind(now),
      db.prepare("DELETE FROM screenplaces_salts WHERE day<?").bind(day),
    ]);
    const cached = await db
      .prepare("SELECT payload FROM screenplaces_cache WHERE id=? AND expiry>?")
      .bind(plan.id, now)
      .first("payload");
    if (cached)
      return {
        body: JSON.parse(cached),
        headers: { "Cache-Control": "public, max-age=3600" },
      };
    const cooldown = await db
      .prepare("SELECT expiry FROM screenplaces_budget WHERE id=? AND expiry>?")
      .bind("source_cooldown", now)
      .first("expiry");
    if (cooldown)
      return spApiError(
        429,
        "source_busy",
        "TMDb is temporarily limiting requests. Please retry later.",
        Math.ceil((cooldown - now) / 1000),
      );
    const spent = await db
      .prepare("SELECT hits FROM screenplaces_budget WHERE id=? AND expiry>?")
      .bind("global", now)
      .first("hits");
    if (spent >= 2000)
      return spApiError(
        429,
        "daily_limit",
        "Today’s film-detail request budget is exhausted. The location catalogue remains available.",
        3600,
      );
    await db
      .prepare(
        "INSERT OR IGNORE INTO screenplaces_salts(day,secret) VALUES(?,?)",
      )
      .bind(day, crypto.randomUUID())
      .run();
    const salt = await db
      .prepare("SELECT secret FROM screenplaces_salts WHERE day=?")
      .bind(day)
      .first("secret");
    const ip = request.headers.get("CF-Connecting-IP") || "unknown",
      digest = await crypto.subtle.digest(
        "SHA-256",
        new TextEncoder().encode(salt + "|screenplaces|" + ip),
      );
    const client = Array.from(new Uint8Array(digest), (v) =>
      v.toString(16).padStart(2, "0"),
    ).join("");
    if (!(await spApiBudget(db, "client:" + client, now, 3600000, 40)))
      return spApiError(
        429,
        "client_wait",
        "Too many uncached film lookups. Please try again later.",
        3600,
      );
    if (!(await spApiBudget(db, "global", now, 86400000, 2000)))
      return spApiError(
        429,
        "daily_limit",
        "Today’s film-detail request budget is exhausted. The location catalogue remains available.",
        3600,
      );
    let response;
    try {
      response = await fetch(plan.target, {
        headers: {
          Authorization: `Bearer ${env.TMDB_READ_ACCESS_TOKEN}`,
          Accept: "application/json",
        },
        signal: AbortSignal.timeout(12000),
        redirect: "manual",
      });
    } catch {
      return spApiError(
        502,
        "source_network",
        "TMDb could not be reached. Please try again later.",
      );
    }
    if (response.status === 429) {
      const retry = Math.max(
        60,
        Math.min(3600, Number(response.headers.get("Retry-After")) || 60),
      );
      await response.body?.cancel();
      await db
        .prepare(
          "INSERT INTO screenplaces_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET expiry=excluded.expiry",
        )
        .bind("source_cooldown", now + retry * 1000)
        .run();
      return spApiError(
        429,
        "source_busy",
        "TMDb is temporarily limiting requests. Please retry shortly.",
        retry,
      );
    }
    if (!response.ok) {
      await response.body?.cancel();
      return spApiError(
        502,
        "source_failure",
        "TMDb could not return this title. Please retry later.",
      );
    }
    const data = screenplacesNormalize(await spApiJson(response));
    const result = { fetched_at: new Date(now).toISOString(), data };
    await db
      .prepare(
        "INSERT INTO screenplaces_cache(id,payload,expiry) VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,expiry=excluded.expiry",
      )
      .bind(plan.id, JSON.stringify(result), now + (data ? 86400000 : 3600000))
      .run();
    await db
      .prepare(
        "DELETE FROM screenplaces_cache WHERE id IN (SELECT id FROM screenplaces_cache ORDER BY expiry DESC LIMIT -1 OFFSET 5000)",
      )
      .run();
    return {
      body: result,
      headers: { "Cache-Control": "public, max-age=3600" },
    };
  } catch {
    return spApiError(
      502,
      "lookup_failed",
      "Film details are temporarily unavailable. The location catalogue remains available.",
    );
  }
}


// Public ADS-B gateway. Inline into CoolCode's Worker after removing export keywords.
// Reuses the existing DB binding / gateway_cache and gateway_budget tables.
// The small structural DB type keeps this module testable with SQLite and D1.
/** @typedef {{prepare:(sql:string)=>any,batch:(statements:any[])=>Promise<any>}} PhDB */
/** @typedef {{DB?:PhDB,ADSBLOL_API_KEY?:string,PLANEHERE_AUTH_MODE?:string,PLANEHERE_DAILY_LIMIT?:string}} PhEnv */
/** @typedef {{lat:number,lon:number,radius:number,centre:{lat:number,lon:number},cacheId:string}} PhQuery */
/** @typedef {Error & {ph?:boolean,status:number,code:string,retry?:number}} PhError */
const phVersion = 'planehere.v1';
const phDay = 86400000;
const phTTL = 300000;
const phUA = 'CoolCode PlaneHere/1.0 (+https://coolcode.ca/planehere/)';
/** @param {number} status @param {string} code @param {string} message @param {number} [retry] */
const phFailure = (status, code, message, retry) => ({status, body:{error:{code,message}}, ...(retry ? {headers:{'Retry-After':String(retry)}} : {})});
/** @param {number} status @param {string} code @param {string} message @param {number} [retry] @returns {never} */
function phThrow(status, code, message, retry) { throw Object.assign(new Error(message), {ph:true,status,code,retry}); }

/** @param {URL} url @returns {PhQuery} */
function planehereQuery(url) {
  const keys = ['lat','lon','radius'];
  for (const [key] of url.searchParams) if (!keys.includes(key) || url.searchParams.getAll(key).length !== 1) phThrow(400,'invalid_parameter','Use one latitude, longitude and radius.');
  /** @param {string} key @param {number} min @param {number} max */
  function number(key, min, max) {
    const raw = url.searchParams.get(key);
    if (raw === null || !/^-?\d+(?:\.\d+)?$/.test(raw) || raw.length > 20) phThrow(400,'invalid_parameter','Enter valid latitude and longitude numbers.');
    const n = Number(raw);
    if (!Number.isFinite(n) || n < min || n > max) phThrow(400,'invalid_parameter','Latitude must be −90 to 90 and longitude −180 to 180.');
    return n;
  }
  const lat = number('lat',-90,90), lon = number('lon',-180,180);
  const radius = Number(url.searchParams.get('radius') || '25');
  if (![10,25,50].includes(radius)) phThrow(400,'invalid_parameter','Choose a radius of 10, 25 or 50 nautical miles.');
  const centre = {lat:Math.round(lat*10)/10,lon:Math.round(lon*10)/10};
  return {lat,lon,radius,centre,cacheId:`${phVersion}:${centre.lat.toFixed(1)}:${centre.lon.toFixed(1)}`};
}

/** @param {any} raw @param {number} [now] */
function planehereNormalize(raw, now = Date.now()) {
  if (!raw || !Array.isArray(raw.ac) || raw.ac.length > 5000 || (raw.msg && raw.msg !== 'No error')) phThrow(502,'invalid_source','The aircraft source returned an unexpected result.');
  const sourceNow = Number(raw.now);
  if (!Number.isFinite(sourceNow) || sourceNow < 1577836800000 || sourceNow > now+60000) phThrow(502,'invalid_source','The aircraft source did not provide a valid observation time.');
  if (sourceNow < now-900000) phThrow(502,'stale_source','The aircraft provider returned observations more than 15 minutes old. Try again later.');
  /** @param {unknown} value @param {number} max */
  const text = (value,max) => typeof value === 'string' ? value.replace(/[\x00-\x1f\x7f]/g,'').trim().slice(0,max) : null;
  /** @param {unknown} value @param {number} min @param {number} max */
  const numeric = (value,min,max) => typeof value === 'number' && Number.isFinite(value) && value >= min && value <= max ? value : null;
  const seen = new Set(), aircraft = [];
  for (const ac of raw.ac) {
    if (!ac || typeof ac !== 'object') continue;
    const hex = text(ac.hex,16), lat = numeric(ac.lat,-90,90), lon = numeric(ac.lon,-180,180), age = numeric(ac.seen_pos,0,86400);
    if (!hex || !/^~?[a-f0-9]{6}$/i.test(hex) || seen.has(hex) || lat === null || lon === null || age === null) continue;
    seen.add(hex);
    aircraft.push({hex,lat,lon,callsign:text(ac.flight,20),registration:text(ac.r,24),aircraft_type:text(ac.t,16),
      altitude_ft:ac.alt_baro === 'ground' ? null : numeric(ac.alt_baro,-2000,100000),
      on_ground:ac.alt_baro === 'ground',speed_knots:numeric(ac.gs,0,2500),track_deg:numeric(ac.track,0,360),
      position_at:new Date(sourceNow-age*1000).toISOString(),source:text(ac.type,32)});
  }
  return {source_at:new Date(sourceNow).toISOString(),aircraft,coverage:'Aircraft with reported positions; reception is incomplete.',licence:'ODbL-1.0',source_url:'https://www.adsb.lol/'};
}

/** @param {PhDB} db */
async function phSchema(db) {
  await db.batch([
    db.prepare('CREATE TABLE IF NOT EXISTS gateway_cache (id TEXT PRIMARY KEY, payload TEXT NOT NULL, expiry INTEGER NOT NULL, touched INTEGER NOT NULL)'),
    db.prepare('CREATE TABLE IF NOT EXISTS gateway_budget (id TEXT PRIMARY KEY, hits INTEGER NOT NULL, expiry INTEGER NOT NULL)'),
  ]);
}
/** @param {PhDB} db @param {string} id @param {number} now @param {number} maximum */
async function phBudget(db,id,now,maximum) {
  const bucket = Math.floor(now/phDay), expiry = (bucket+1)*phDay;
  const row = await db.prepare('INSERT INTO gateway_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET hits=hits+1 WHERE hits<? RETURNING hits').bind(`${id}:${bucket}`,expiry,maximum).first();
  if (!row) phThrow(429,'quota_wait','The shared daily aircraft allowance has been used. Previously loaded observations remain available.',Math.ceil((expiry-now)/1000));
}
/** @param {PhDB} db @param {string} id @param {number} now */
async function phFlag(db,id,now) {return db.prepare('SELECT expiry FROM gateway_budget WHERE id=? AND expiry>?').bind(id,now).first();}
/** @param {PhDB} db @param {string} id @param {number} expiry */
async function phSetFlag(db,id,expiry) {return db.prepare('INSERT INTO gateway_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET expiry=excluded.expiry').bind(id,expiry).run();}
/** @param {Response} response @param {number} now */
function phRetry(response,now) {
  const h = response.headers.get('Retry-After');
  let n = /^\d+$/.test(h || '') ? Number(h) : (Date.parse(h || '')-now)/1000;
  if (!Number.isFinite(n)) n = 300;
  return Math.max(60,Math.min(86400,Math.ceil(n)));
}
/** @param {Response} response */
async function phRead(response) {
  const maximum = 1500000;
  if (Number(response.headers.get('Content-Length')) > maximum) {await response.body?.cancel();phThrow(502,'source_too_large','The aircraft source exceeded its response limit.');}
  if (!response.body) phThrow(502,'invalid_source','The aircraft source returned no data.');
  const reader = response.body.getReader(), chunks=[];let size=0;
  try {for (;;) {const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>maximum)phThrow(502,'source_too_large','The aircraft source exceeded its response limit.');chunks.push(value);}}
  catch(error) {await reader.cancel().catch(()=>{});throw error;}
  const bytes=new Uint8Array(size);let at=0;for(const c of chunks){bytes.set(c,at);at+=c.length;}
  try{return JSON.parse(new TextDecoder('utf-8',{fatal:true,ignoreBOM:false}).decode(bytes));}catch{phThrow(502,'invalid_source','The aircraft source returned unreadable data.');}
}
/** @param {PhQuery} query @param {PhEnv} env @param {PhDB} db @param {number} now @param {typeof fetch} fetcher */
async function phFetch(query,env,db,now,fetcher) {
  const mode = env.PLANEHERE_AUTH_MODE || 'auto';
  if (!['auto','key','anonymous'].includes(mode)) phThrow(503,'configuration_error','The aircraft service authentication mode needs review.');
  const configuredKey = typeof env.ADSBLOL_API_KEY === 'string' ? env.ADSBLOL_API_KEY.trim() : '';
  if (mode === 'key' && !configuredKey) phThrow(503,'not_configured','The aircraft service key has not been configured.');
  const keyDisabled = mode === 'auto' && await phFlag(db,'planehere:key-rest',now);
  let key = mode === 'anonymous' || keyDisabled ? '' : configuredKey;
  const configuredLimit = Number(env.PLANEHERE_DAILY_LIMIT || 450);
  if (!Number.isInteger(configuredLimit) || configuredLimit < 1 || configuredLimit > 7000) phThrow(503,'configuration_error','The aircraft service request limit needs review.');
  const target = `https://api.adsb.lol/v2/lat/${query.centre.lat.toFixed(1)}/lon/${query.centre.lon.toFixed(1)}/dist/60`;
  const signal = AbortSignal.timeout(12000);
  for (let attempt=0;attempt<2;attempt++) {
    await phBudget(db,'planehere:total',Date.now(),configuredLimit);
    if (!key) await phBudget(db,'planehere:anonymous',Date.now(),450);
    /** @type {Record<string,string>} */
    const headers = {Accept:'application/json','User-Agent':phUA};if (key) headers['x-api-key']=key;
    let response;
    try {response=await fetcher(target,{headers,redirect:'manual',signal});}
    catch {phThrow(signal.aborted?504:502,'source_unavailable',signal.aborted?'The aircraft source took too long to respond.':'The aircraft source is temporarily unreachable.');}
    if ([401,403].includes(response.status) && key && mode === 'auto' && attempt === 0) {
      // 401 means failed authentication. A 403 can instead be a policy block; only
      // an explicit key-authentication error allows the documented anonymous path.
      let keyRejected=response.status===401;
      if(response.status===403){
        let reason='';try{const detail=await phRead(response);reason=JSON.stringify(detail).slice(0,8000);}catch{}
        keyRejected=/(?:invalid|expired|revoked)[_ \-]*(?:api[_ \-]*)?key|(?:api[_ \-]*)?key[_ \-]*(?:invalid|expired|revoked)/i.test(reason);
      }
      if(keyRejected){await response.body?.cancel().catch(()=>{});await phSetFlag(db,'planehere:key-rest',Date.now()+3600000);key='';continue;}
    }
    if (response.status === 429) {
      const retry=phRetry(response,Date.now());await response.body?.cancel();await phSetFlag(db,'planehere:provider-rest',Date.now()+retry*1000);
      phThrow(429,'source_wait','The aircraft provider has asked us to pause. Please retry after the indicated delay.',retry);
    }
    if (!response.ok) {await response.body?.cancel().catch(()=>{});phThrow(502,'source_unavailable','The aircraft source could not complete this lookup.');}
    const data=planehereNormalize(await phRead(response));
    return {fetched_at:new Date().toISOString(),data:{...data,query_centre:query.centre,query_radius_nm:60,access_mode:key?'key':'anonymous'}};
  }
  phThrow(502,'source_unavailable','The aircraft source could not complete this lookup.');
}

/** @param {Request} request @param {PhEnv} env @param {unknown} ctx @param {{fetcher?:typeof fetch}} [options] */
async function planehereApiHandle(request,env,ctx,options={}) {
  const fetcher=options.fetcher || fetch;let db,lease;
  try {
    const url=new URL(request.url),origin=request.headers.get('Origin');
    if (origin && origin !== 'https://coolcode.ca') return phFailure(403,'origin_denied','Origin is not allowed.');
    if (url.pathname !== '/api/planehere/nearby') return phFailure(404,'unknown_endpoint','Unknown aircraft endpoint.');
    if (request.method==='OPTIONS') return {status:204};
    if (request.method!=='GET') return phFailure(405,'method_denied','Use GET for aircraft lookups.');
    const query=planehereQuery(url),now=Date.now();db=env.DB;
    if(!db)return phFailure(503,'storage_unavailable','The shared aircraft cache is unavailable.');
    await phSchema(db);
    const cached=await db.prepare('SELECT payload FROM gateway_cache WHERE id=? AND expiry>?').bind(query.cacheId,now).first('payload');
    if(cached)return {body:JSON.parse(cached),headers:{'Cache-Control':'public, max-age=30'}};
    const resting=await phFlag(db,'planehere:provider-rest',now);
    if(resting)return phFailure(429,'source_wait','The aircraft provider has asked us to pause.',Math.ceil((resting.expiry-now)/1000));
    const leaseId='planehere:lease:'+query.cacheId;
    const acquired=await db.prepare('INSERT INTO gateway_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET expiry=excluded.expiry WHERE expiry<=? RETURNING hits').bind(leaseId,now+20000,now).first();
    if(!acquired)return phFailure(429,'refresh_in_progress','This area is being refreshed. Try again in a few seconds.',5);
    lease={id:leaseId,expiry:now+20000};
    const result=await phFetch(query,env,db,now,fetcher),payload=JSON.stringify(result),captured=Date.now();
    if(new TextEncoder().encode(payload).byteLength>500000)phThrow(502,'source_too_large','The aircraft result exceeds the shared cache limit.');
    await db.batch([
      db.prepare('INSERT INTO gateway_cache(id,payload,expiry,touched) VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,expiry=excluded.expiry,touched=excluded.touched').bind(query.cacheId,payload,captured+phTTL,captured),
      db.prepare("DELETE FROM gateway_cache WHERE id LIKE 'planehere.v1:%' AND expiry<=?").bind(captured),
      db.prepare("DELETE FROM gateway_cache WHERE id IN (SELECT id FROM gateway_cache WHERE id LIKE 'planehere.v1:%' ORDER BY touched DESC,id DESC LIMIT -1 OFFSET 128)"),
      db.prepare("DELETE FROM gateway_budget WHERE id LIKE 'planehere:%' AND expiry<=?").bind(captured),
    ]);
    return {body:result,headers:{'Cache-Control':'public, max-age=30'}};
  } catch(error) {
    if(error && typeof error==='object' && 'ph' in error){const failure=/** @type {PhError} */(error);return phFailure(failure.status,failure.code,failure.message,failure.retry);}
    return phFailure(503,'temporarily_unavailable','The shared aircraft service is temporarily unavailable.');
  } finally {
    if(db&&lease)await db.prepare('DELETE FROM gateway_budget WHERE id=? AND expiry=?').bind(lease.id,lease.expiry).run().catch(()=>{});
  }
}


// Bounded server adapters for the second discovery batch. No client-chosen upstreams.
// Existing DB binding and Secret values are reused; keys and request bodies are never logged.
const sbVersion = 'second-batch.v1';
const sbDay = 86400000;

async function sbHash(value) {
  const hash=await crypto.subtle.digest('SHA-256',encoder.encode(value));
  return Array.from(new Uint8Array(hash), b=>b.toString(16).padStart(2,'0')).join('');
}

async function sbSchema(db) {
  await db.batch([
    db.prepare('CREATE TABLE IF NOT EXISTS discovery_cache (id TEXT PRIMARY KEY,payload TEXT NOT NULL,expiry INTEGER NOT NULL)'),
    db.prepare('CREATE TABLE IF NOT EXISTS discovery_budget (id TEXT PRIMARY KEY,hits INTEGER NOT NULL,expiry INTEGER NOT NULL)'),
    db.prepare('CREATE TABLE IF NOT EXISTS measure_budget (month TEXT PRIMARY KEY,hits INTEGER NOT NULL,day TEXT NOT NULL,day_hits INTEGER NOT NULL,expiry INTEGER NOT NULL)'),
  ]);
}

async function sbBudget(db,id,now,expiry,maximum) {
  // One atomic conditional write. Simultaneous Worker instances cannot overspend.
  const row=await db.prepare('INSERT INTO discovery_budget(id,hits,expiry) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET hits=hits+1 WHERE hits<? RETURNING hits').bind(id,expiry,maximum).first();
  if(!row) apiThrow(429,'quota_wait','This source has reached its shared allowance. Cached results and local calculations remain available.',Math.max(1,Math.ceil((expiry-now)/1000)));
}

async function sbCacheGet(db,id,now) {
  const value=await db.prepare('SELECT payload FROM discovery_cache WHERE id=? AND expiry>?').bind(id,now).first('payload');
  return value ? JSON.parse(value) : null;
}

async function sbCachePut(db,id,value,ttl,now) {
  const payload=JSON.stringify(value);
  if(encoder.encode(payload).byteLength>500000) return;
  await db.batch([
    db.prepare('DELETE FROM discovery_cache WHERE expiry<=?').bind(now),
    db.prepare('DELETE FROM discovery_budget WHERE expiry<=?').bind(now),
    db.prepare('DELETE FROM measure_budget WHERE expiry<=?').bind(now),
    db.prepare('INSERT INTO discovery_cache(id,payload,expiry) VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,expiry=excluded.expiry').bind(id,payload,now+ttl),
    db.prepare('DELETE FROM discovery_cache WHERE id IN (SELECT id FROM discovery_cache ORDER BY expiry DESC,id DESC LIMIT -1 OFFSET 512)'),
  ]);
}

async function sbRead(target,headers,limit=1000000,timeout=12000) {
  const signal=AbortSignal.timeout(timeout);
  try {
    const response=await fetch(target,{headers,redirect:'manual',signal});
    if(!response.ok){await response.body?.cancel();apiThrow(response.status===429?429:502,'source_unavailable','The upstream source could not complete this request. Try again later.',response.status===429?60:undefined);}
    return await apiRead(response,limit);
  } catch(error) {
    if(error.api) throw error;
    if(signal.aborted) apiThrow(504,'source_timeout','The upstream source took too long to respond. Please retry later.');
    apiThrow(502,'source_network','The upstream source could not be reached. Please retry later.');
  }
}

async function sbJson(target,headers,limit=1000000) {
  const text=await sbRead(target,headers,limit);
  try{return JSON.parse(text);}catch{apiThrow(502,'invalid_source','The source returned invalid JSON.');}
}

function sbImage(path) {
  return typeof path==='string' && /^\/[A-Za-z0-9_-]+\.(jpg|png|webp)$/.test(path) ? 'https://image.tmdb.org/t/p/w342'+path : null;
}

function sbPerson(person,payload,wikidata) {
  if(!person || !Number.isSafeInteger(person.id) || person.id<=0 || typeof person.name!=='string' || !Array.isArray(payload.cast)) apiThrow(502,'invalid_source','The actor source returned an unexpected result.');
  if(payload.id!==undefined && payload.id!==person.id) apiThrow(502,'invalid_source','The source credits belong to a different person.');
  const seen=new Set();
  const credits=payload.cast.filter(x=>x && x.adult!==true && ['movie','tv'].includes(x.media_type) && Number.isSafeInteger(x.id) && x.id>0)
    .sort((a,b)=>(Number(b.vote_count)||0)-(Number(a.vote_count)||0))
    .filter(x=>{const key=x.media_type+':'+x.id;if(seen.has(key))return false;seen.add(key);return true;})
    .slice(0,30).map(x=>({id:x.id,media_type:x.media_type,title:String(x.title||x.name||'').slice(0,300),release_date:/^\d{4}-\d{2}-\d{2}$/.test(x.release_date||x.first_air_date||'') ? (x.release_date||x.first_air_date) : null,character:String(x.character||'').slice(0,500),url:`https://www.themoviedb.org/${x.media_type}/${x.id}`,poster:sbImage(x.poster_path)}));
  return {person:{wikidata,id:person.id,name:person.name.slice(0,200),profile:sbImage(person.profile_path),url:`https://www.themoviedb.org/person/${person.id}`},credits,attribution:'This product uses the TMDB API but is not endorsed or certified by TMDB.'};
}

async function sbPersonHandle(request,env,url,db,now) {
  if(url.pathname!=='/api/screenradar/person') return apiFailure(404,'unknown_endpoint','Unknown actor endpoint.');
  const p=apiParams(url,['wikidata']), wikidata=p('wikidata',/^Q[1-9]\d{0,11}$/);
  if(!env.TMDB_READ_ACCESS_TOKEN) return apiFailure(503,'not_configured','Actor credits are awaiting the site API configuration.');
  const id=sbVersion+':person:'+wikidata, cached=await sbCacheGet(db,id,now);
  if(cached) return {body:cached};
  const day=Math.floor(now/sbDay);
  await sbBudget(db,'tmdb-people:'+day,now,(day+1)*sbDay,1000);
  const headers={Accept:'application/json',Authorization:'Bearer '+env.TMDB_READ_ACCESS_TOKEN,'User-Agent':apiUA};
  const found=await sbJson(`https://api.themoviedb.org/3/find/${wikidata}?external_source=wikidata_id&language=en-US`,headers,524288);
  if(!Array.isArray(found.person_results)) apiThrow(502,'invalid_source','The actor source returned an unexpected result.');
  // Ambiguous mappings are not silently assigned to the first person.
  if(found.person_results.length!==1) {
    const result={fetched_at:new Date(now).toISOString(),data:null};
    await sbCachePut(db,id,result,3600000,now); return {body:result};
  }
  const person=found.person_results[0];
  if(!Number.isSafeInteger(person.id)||person.id<=0) apiThrow(502,'invalid_source','The actor source returned an invalid identifier.');
  const credits=await sbJson(`https://api.themoviedb.org/3/person/${person.id}/combined_credits?language=en-US`,headers);
  const captured=Date.now(), result={fetched_at:new Date(captured).toISOString(),data:sbPerson(person,credits,wikidata)};
  await sbCachePut(db,id,result,sbDay,captured); return {body:result};
}

function sbArchivePlan(url) {
  const p=apiParams(url,['domain','mode','from','to']);
  const domain=p('domain',/^[a-zA-Z0-9.-]{1,253}$/).toLowerCase();
  if(!domain.includes('.') || !/^[a-z]{2,63}$/.test(domain.split('.').at(-1)) || domain.split('.').some(x=>!x || x.length>63 || !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(x)) || /\.(?:localhost|local|internal|lan|home|test|invalid|example|onion)$/.test(domain)) apiThrow(400,'invalid_parameter','Enter a public domain name without a URL, path or IP address.');
  const mode=p('mode',/^(homepage|pages)$/,'homepage'),limit=mode==='homepage'?2500:500;
  const target=new URL('https://web.archive.org/cdx/search/cdx');
  target.searchParams.set('url',domain+'/');
  target.searchParams.set('matchType',mode==='homepage'?'exact':'host');
  target.searchParams.set('output','json');target.searchParams.set('fl','timestamp,original,statuscode,mimetype');
  target.searchParams.append('filter','statuscode:200');target.searchParams.append('filter','mimetype:text/html');
  target.searchParams.set('limit',String(limit+1));
  if(mode==='pages') {
    target.searchParams.set('collapse','urlkey');
    target.searchParams.append('filter','original:.*[/:](about|contact)([-_/][^?]*)?(\\.(html?|php|aspx?))?/?(\\?.*)?$');
  }
  let from='',to='';
  if(url.searchParams.has('from')) {from=p('from',/^(?:19|20)\d{2}$/);target.searchParams.set('from',from);}
  if(url.searchParams.has('to')) {to=p('to',/^(?:19|20)\d{2}$/);target.searchParams.set('to',to);}
  if(from && to && from>to) apiThrow(400,'invalid_parameter','The start year must not be after the end year.');
  return {domain,mode,limit,target};
}

function sbArchiveRows(payload,plan,now) {
  if(!Array.isArray(payload)) apiThrow(502,'invalid_source','The archive returned an unexpected result.');
  const header=['timestamp','original','statuscode','mimetype'];
  if(payload.length && JSON.stringify(payload[0])!==JSON.stringify(header)) apiThrow(502,'invalid_source','The archive returned an unexpected column layout.');
  const all=payload.slice(1), rows=[];
  for(const row of all.slice(0,plan.limit)) {
    if(!Array.isArray(row)||row.length!==4||row.some(v=>typeof v!=='string')||!/^\d{14}$/.test(row[0])||row[2]!=='200'||row[3]!=='text/html'||row[1].length>2048) apiThrow(502,'invalid_source','The archive returned a malformed capture.');
    const stamp=row[0],iso=`${stamp.slice(0,4)}-${stamp.slice(4,6)}-${stamp.slice(6,8)}T${stamp.slice(8,10)}:${stamp.slice(10,12)}:${stamp.slice(12,14)}Z`,date=new Date(iso);
    if(!Number.isFinite(date.getTime())||date.toISOString().replace(/[-:TZ.]/g,'').slice(0,14)!==stamp || (plan.target.searchParams.has('from') && stamp.slice(0,4)<plan.target.searchParams.get('from')) || (plan.target.searchParams.has('to') && stamp.slice(0,4)>plan.target.searchParams.get('to'))) apiThrow(502,'invalid_source','The archive returned a capture outside the requested date range or with an invalid date.');
    let original;try{original=new URL(row[1]);}catch{apiThrow(502,'invalid_source','The archive returned an invalid original URL.');}
    if(!['http:','https:'].includes(original.protocol)||original.username||original.password||original.port||original.hostname.replace(/^www\./,'')!==plan.domain.replace(/^www\./,'')) apiThrow(502,'invalid_source','The archive returned a capture outside the requested hostname.');
    if(plan.mode==='homepage' && (original.pathname!=='/'||original.search)) apiThrow(502,'invalid_source','The archive returned a non-homepage capture.');
    if(plan.mode==='pages' && !/(?:^|\/)(?:about|contact)(?:[-_/][^?]*)?(?:\.(?:html?|php|aspx?))?\/?$/i.test(original.pathname)) continue;
    rows.push(row);
  }
  return {rows:[header,...rows],truncated:all.length>plan.limit,checked_at:new Date(now).toISOString(),scope:plan.mode,limit:plan.limit,source_url:plan.target.href};
}

async function sbArchiveHandle(request,env,url,db,now) {
  if(url.pathname!=='/api/domain-biography/archive') return apiFailure(404,'unknown_endpoint','Unknown archive endpoint.');
  const plan=sbArchivePlan(url),id=sbVersion+':archive:'+await sbHash(plan.target.href),cached=await sbCacheGet(db,id,now);
  if(cached) return {body:cached};
  const day=Math.floor(now/sbDay);await sbBudget(db,'archive-cdx:'+day,now,(day+1)*sbDay,1000);
  const payload=await sbJson(plan.target.href,{Accept:'application/json','User-Agent':apiUA});
  const captured=Date.now(),result={fetched_at:new Date(captured).toISOString(),data:sbArchiveRows(payload,plan,captured)};
  await sbCachePut(db,id,result,6*3600000,captured);return {body:result};
}

async function sbMeasureHandle(request,env,url,db,now) {
  if(url.pathname!=='/api/measurebench/answer') return apiFailure(404,'unknown_endpoint','Unknown calculation endpoint.');
  apiParams(url,[]);
  if(!/^application\/json(?:;|$)/i.test(request.headers.get('Content-Type')||'')) return apiFailure(415,'content_type','Send a JSON calculation request.');
  let value;try{value=await body(request,2048);}catch{return apiFailure(400,'invalid_request','Send one query of at most 300 characters.');}
  if(Object.keys(value).some(k=>k!=='query')||typeof value.query!=='string') return apiFailure(400,'invalid_request','Send one calculation query.');
  const query=value.query.trim().replace(/\s+/g,' ');
  if(!query||query.length>300||/[\x00-\x1f\x7f]/.test(query)) return apiFailure(400,'invalid_request','Use a query of 1–300 characters.');
  if(!env.WOLFRAM_APP_ID) return apiFailure(503,'not_configured','Optional Wolfram answers are awaiting the site API configuration. Local calculations are ready.');
  const id=sbVersion+':wolfram:'+await sbHash(query),cached=await sbCacheGet(db,id,now);
  if(cached) return {body:{...cached,cached:true}};
  const date=new Date(now),day=Math.floor(now/sbDay),month=date.toISOString().slice(0,7),monthEnd=Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,1);
  // Reserve both limits in one atomic write, including failed provider calls.
  // Rejected daily requests cannot consume the rest of the month's allowance.
  const usage=await db.prepare('INSERT INTO measure_budget(month,hits,day,day_hits,expiry) VALUES(?,1,?,1,?) ON CONFLICT(month) DO UPDATE SET hits=hits+1,day=excluded.day,day_hits=CASE WHEN day=excluded.day THEN day_hits+1 ELSE 1 END WHERE hits<1000 AND CAST(day AS INTEGER)<=CAST(excluded.day AS INTEGER) AND (day<>excluded.day OR day_hits<50) RETURNING hits').bind(month,String(day),monthEnd).first();
  if(!usage) {
    const spent=await db.prepare('SELECT hits FROM measure_budget WHERE month=?').bind(month).first('hits');
    apiThrow(429,'quota_wait','The shared Wolfram allowance is reached (50 requests per UTC day, 1,000 per calendar month). Cached answers and local calculations remain available.',Math.ceil(((spent>=1000?monthEnd:(day+1)*sbDay)-now)/1000));
  }
  const target=new URL('https://api.wolframalpha.com/v1/result');
  target.searchParams.set('i',query);target.searchParams.set('appid',env.WOLFRAM_APP_ID);target.searchParams.set('units','metric');target.searchParams.set('timeout','5');
  const answer=(await sbRead(target.href,{Accept:'text/plain','User-Agent':apiUA},16384,8000)).trim();
  if(!answer||answer.length>8000||/^(?:Error\b|Invalid appid|Appid missing|<html|<!DOCTYPE)/i.test(answer)||answer.includes(env.WOLFRAM_APP_ID)) apiThrow(502,'no_answer','Wolfram could not provide a short answer for this query.');
  const captured=Date.now(),result={answer,source:'Wolfram Alpha',cached:false,fetched_at:new Date(captured).toISOString()};
  await sbCachePut(db,id,result,7*sbDay,captured);return {body:result};
}

async function secondBatchApiHandle(request,env,ctx) {
  try {
    const url=new URL(request.url),origin=request.headers.get('Origin'),measure=url.pathname.startsWith('/api/measurebench/');
    if(origin && origin!==ORIGIN) return apiFailure(403,'origin_denied','Origin is not allowed.');
    if(request.method==='OPTIONS') return {status:204};
    if(request.method!==(measure?'POST':'GET')) return apiFailure(405,'method_denied',measure?'Use POST for optional calculation requests.':'Use GET for public data requests.');
    if(measure && origin!==ORIGIN) return apiFailure(403,'origin_denied','Optional calculation requests must come from CoolCode.');
    const db=env.DB,now=Date.now();if(!db) return apiFailure(503,'storage_unavailable','The shared request limiter is unavailable.');
    if(!await allowed(db,request,new Date(now),'discovery-api')) return apiFailure(429,'client_wait','Too many requests. Please retry later.',300);
    await sbSchema(db);
    if(measure) return await sbMeasureHandle(request,env,url,db,now);
    if(url.pathname.startsWith('/api/screenradar/')) return await sbPersonHandle(request,env,url,db,now);
    return await sbArchiveHandle(request,env,url,db,now);
  }catch(error){
    if(error.api) return apiFailure(error.status,error.code,error.message,error.retry);
    return apiFailure(503,'temporarily_unavailable','The source or shared request service is temporarily unavailable. Local tools remain available.');
  }
}


async function body(request, limit) {
  if (Number(request.headers.get('content-length')) > limit) throw new RangeError();
  if (!request.body) throw new SyntaxError();
  const reader = request.body.getReader();
  const chunks = [];
  let length = 0;
  while (true) {
    const {done,value} = await reader.read();
    if (done) break;
    length += value.length;
    if (length > limit) { await reader.cancel(); throw new RangeError(); }
    chunks.push(value);
  }
  const bytes = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk,offset); offset += chunk.length; }
  let text;
  try { text = new TextDecoder('utf-8',{fatal:true,ignoreBOM:false}).decode(bytes); }
  catch { throw new SyntaxError('Invalid UTF-8 request.'); }
  const value = JSON.parse(text);
  if (!value || Array.isArray(value) || typeof value !== 'object') throw new SyntaxError();
  return value;
}

function eventRecord(value) {
  if (!known.has(value.tool) || value.tool==='site' && value.type!=='pageview') return null;
  if (value.type==='pageview') return {type:'pageview',tool:value.tool,experiment:'',variant:''};
  if (!['impression','click'].includes(value.type) || !variants.has(value.variant) ||
      typeof value.experiment!=='string' || value.experiment.length>48 || !experimentName.test(value.experiment)) return null;
  return {type:value.type,tool:value.tool,experiment:value.experiment,variant:value.variant};
}

function reportRecord(value) {
  if (!known.has(value.tool) || !categories.has(value.category) || typeof value.description!=='string' ||
      (value.website!=null && value.website!=='') || !value.description.trim() || value.description.trim().length>2000) return null;
  return {tool:value.tool,category:value.category,description:value.description.trim()};
}

// Discard prior daily salts and expired counters the first time a new UTC day is used.
async function allowed(db, request, now, kind) {
  const day = dayOf(now);
  const ms = now.getTime();
  let salt = await db.prepare('SELECT secret FROM salts WHERE day=?').bind(day).first('secret');
  if (!salt) {
    await db.batch([
      db.prepare('INSERT OR IGNORE INTO salts(day,secret) VALUES(?,?)').bind(day,crypto.randomUUID()),
      db.prepare('DELETE FROM salts WHERE day<?').bind(day),
      db.prepare('DELETE FROM limits WHERE expiry<=?').bind(ms),
    ]);
    salt = await db.prepare('SELECT secret FROM salts WHERE day=?').bind(day).first('secret');
  }
  const addr = request.headers.get('CF-Connecting-IP') || 'shared';
  const raw = await crypto.subtle.digest('SHA-256',encoder.encode(salt+'|'+addr+'|'+kind));
  const client = Array.from(new Uint8Array(raw).slice(0,16),b=>b.toString(16).padStart(2,'0')).join('');
  const width = kind==='report' ? 3600000 : 300000;
  const maximum = kind==='report' ? 8 : 240;
  const bucket = Math.floor(ms/width);
  const record = await db.prepare(
    'INSERT INTO limits(bucket,kind,client,hits,expiry) VALUES(?,?,?,1,?) ON CONFLICT(bucket,kind,client) DO UPDATE SET hits=hits+1 WHERE hits<? RETURNING hits'
  ).bind(bucket,kind,client,(bucket+1)*width,maximum).first();
  return Boolean(record);
}

async function owner(request) {
  const auth = request.headers.get('authorization') || '';
  if (!/^Bearer [^\s]{8,512}$/i.test(auth)) return errorResponse(401,'Owner sign-in is required.');
  let response;
  try {
    response=await fetch('https://api.github.com/user',{headers:{Authorization:auth,Accept:'application/vnd.github+json','User-Agent':'CoolCode-owner-check','X-GitHub-Api-Version':'2022-11-28'},redirect:'manual',signal:AbortSignal.timeout(6000)});
    if (response.status===401) return errorResponse(401,'GitHub did not accept this sign-in.');
    if (!response.ok) return errorResponse(503,'GitHub identity check is unavailable.');
    const user=await response.json();
    if (user.id!==OWNER) return errorResponse(403,'This account does not own CoolCode.');
    return null;
  } catch { return errorResponse(503,'GitHub identity check is unavailable.'); }
}

async function stats(db,url,now) {
  const days=Number(url.searchParams.get('days') || 7);
  if (![7,28].includes(days)) return errorResponse(400,'Choose 7 or 28 days.');
  const through=dayOf(now), from=dayOf(new Date(now.getTime()-(days-1)*86400000));
  const run=sql=>db.prepare(sql).bind(from,through);
  const [tools,daily,experiments,cards,reportCount]=await db.batch([
    run("SELECT tool,SUM(total) views FROM counts WHERE day BETWEEN ? AND ? AND type='pageview' GROUP BY tool ORDER BY views DESC,tool"),
    run("SELECT day,SUM(total) views FROM counts WHERE day BETWEEN ? AND ? AND type='pageview' GROUP BY day ORDER BY day"),
    run("SELECT experiment,variant,SUM(CASE WHEN type='impression' THEN total ELSE 0 END) impressions,SUM(CASE WHEN type='click' THEN total ELSE 0 END) clicks FROM counts WHERE day BETWEEN ? AND ? AND type IN ('impression','click') GROUP BY experiment,variant ORDER BY experiment,variant"),
    run("SELECT experiment,variant,tool,SUM(CASE WHEN type='impression' THEN total ELSE 0 END) impressions,SUM(CASE WHEN type='click' THEN total ELSE 0 END) clicks FROM counts WHERE day BETWEEN ? AND ? AND type IN ('impression','click') GROUP BY experiment,variant,tool ORDER BY experiment,variant,tool"),
    db.prepare("SELECT COUNT(*) count FROM reports WHERE status='open'"),
  ]);
  return {body:{days,from,through,totalViews:tools.results.reduce((n,row)=>n+row.views,0),openReports:reportCount.results[0].count,tools:tools.results,daily:daily.results,experiments:experiments.results,cards:cards.results}};
}

async function reports(db,url) {
  const before=url.searchParams.get('before');
  if (before && !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z~[\da-f-]{36}$/.test(before)) return errorResponse(400,'Invalid report cursor.');
  const [when,id] = before ? before.split('~') : ['9999',''];
  const result=await db.prepare('SELECT id,tool,category,description,created,status FROM reports WHERE (created,id)<(?,?) ORDER BY created DESC,id DESC LIMIT 101').bind(when,id).all();
  const rows=result.results.slice(0,100), last=rows.at(-1);
  return {body:{reports:rows,next:result.results.length>100 ? last.created+'~'+last.id : null}};
}

async function handle(request,env,ctx) {
  const db=env.DB, url=new URL(request.url),path=url.pathname;
  if (path.startsWith('/api/')) return apiHandle(request,env,ctx);
  const origin=request.headers.get('Origin');
  const publicPath=['/event','/report'].includes(path);
  const adminPath=['/admin/stats','/admin/reports'].includes(path)||/^\/admin\/reports\/[\da-f-]{36}$/.test(path);
  // Public catalogue IDs only: read-only deployment verification, no visitor data or writes.
  if (path === '/registry' && request.method === 'GET') {
    return {body: {schema: 'coolcode.tool-registry.v1', tool_ids: toolList}};
  }
  if (path === '/health' && request.method === 'GET') {
    // Compile against the expected tables without reading any visitor records.
    await db.prepare('SELECT counts.day, limits.bucket, reports.id, salts.day FROM counts, limits, reports, salts LIMIT 0').all();
    return {body: {ok: true}};
  }
  if (!publicPath && !adminPath) return errorResponse(404, 'Unknown endpoint.');
  if ((publicPath && origin!==ORIGIN) || (origin && origin!==ORIGIN)) return errorResponse(403,'Origin is not allowed.');
  if (request.method==='OPTIONS') return {status:204};
  if (adminPath) {
    const denied=await owner(request);
    if (denied) return denied;
    if (path==='/admin/stats'&&request.method==='GET') return stats(db,url,new Date());
    if (path==='/admin/reports'&&request.method==='GET') return reports(db,url);
    if (path.startsWith('/admin/reports/')&&request.method==='PATCH') {
      const input=await body(request,300);
      if (!['open','resolved'].includes(input.status)) return errorResponse(400,'Unknown report status.');
      const row=await db.prepare('UPDATE reports SET status=? WHERE id=? RETURNING id,status').bind(input.status,path.split('/').pop()).first();
      return row ? {body:{ok:true,...row}} : errorResponse(404,'Report not found.');
    }
    return errorResponse(405,'Unsupported method.');
  }
  if (request.method!=='POST') return errorResponse(405,'Unsupported method.');
  const isReport=path==='/report';
  const mime=(request.headers.get('content-type')||'').split(';')[0].trim().toLowerCase();
  if (!(isReport ? ['application/json'] : ['application/json','text/plain']).includes(mime)) return errorResponse(415,'Unsupported content type.');
  const input=await body(request,isReport?10000:1000);
  const row=isReport ? reportRecord(input) : eventRecord(input);
  if (!row) return errorResponse(400,isReport?'Check the tool, category and description.':'Invalid event.');
  const now=new Date();
  if (!await allowed(db,request,now,isReport?'report':'event')) return errorResponse(429,'Please try again later.');
  if (isReport) {
    const id=crypto.randomUUID();
    await db.prepare("INSERT INTO reports(id,tool,category,description,created,status) VALUES(?,?,?,?,?,'open')").bind(id,row.tool,row.category,row.description,now.toISOString()).run();
    return {status:201,body:{ok:true,id}};
  }
  await db.prepare('INSERT INTO counts(day,tool,experiment,variant,type,total) VALUES(?,?,?,?,?,1) ON CONFLICT(day,tool,experiment,variant,type) DO UPDATE SET total=total+1').bind(dayOf(now),row.tool,row.experiment,row.variant,row.type).run();
  return {status:204};
}

export default {
  async fetch(request,env,ctx) {
    if(request.method==='POST' && env.LOC_DIAGNOSTIC_CONFIG){
      const diagnostic=await newspaperDiagnostic(request,env);
      if(diagnostic) return diagnostic;
    }
    const headers={'Cache-Control':cacheControl,Vary:'Origin','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'};
    if (request.headers.get('Origin')===ORIGIN) {
      headers['Access-Control-Allow-Origin']=ORIGIN;
      headers['Access-Control-Allow-Methods']='GET, POST, PATCH, OPTIONS';
      headers['Access-Control-Allow-Headers']='Authorization, Content-Type';
      headers['Access-Control-Max-Age']='600';
      headers['Access-Control-Expose-Headers']='Retry-After, X-CoolCode-Fetched-At';
    }
    let result;
    try { result=await handle(request,env,ctx); }
    catch (e) {
      if (e instanceof RangeError) result=errorResponse(413,'Request is too large.');
      else if (e instanceof SyntaxError) result=errorResponse(400,'Invalid JSON request.');
      else result=errorResponse(503,'Service temporarily unavailable.');
    }
    if (result.rawResponse) {
      const raw=result.rawResponse;
      for(const name of ['Content-Type','X-CoolCode-Fetched-At']){
        const value=raw.headers.get(name);if(value)headers[name]=value;
      }
      return new Response(raw.body,{status:raw.status,headers});
    }
    if (result.body) headers['Content-Type']='application/json; charset=utf-8';
    return new Response(result.body?JSON.stringify(result.body):null,{status:result.status||200,headers:{...headers,...result.headers}});
  },
};
